func SelfUpdateProgram(id, cell, from, to string, controllers []rollout.Unit, hosts []rollout.Unit,
	policy rollout.Policy,
) Program {
	var program Program
	if len(controllers) > 0 {
		program = append(program, rollout.Spec{RolloutID: entityid.Derive(rollout.ControllerReleaseDomain, id), Kind: rollout.KindController, Cell: cell,
			FromDigest: from, ToDigest: to, Units: controllers, Policy: policy})
	}
	if len(hosts) > 0 {
		program = append(program, rollout.Spec{RolloutID: entityid.Derive(rollout.HostReleaseDomain, id), Kind: rollout.KindHost, Cell: cell,
			FromDigest: from, ToDigest: to, Units: hosts, Policy: policy})
	}
	return program
}

release_program.text:
func (p ReleaseProgram) Program(ctx context.Context) (Program, error) {
	desired, _, err := p.Store.Desired(ctx)
	if err != nil {
		return nil, err
	}
	release := desired.Release
	if release.Generation == 0 || desired.Paused || len(p.Controllers) == 0 {
		return nil, nil
	}
	id := rollout.ReleaseRolloutID(release.Generation)
	var program Program
	controllers, done, err := p.rollout(ctx, entityid.Derive(rollout.ControllerReleaseDomain, id), rollout.KindController, p.Controllers, desired)
	if err != nil {
		return nil, err
	}
	if controllers != nil {
		program = append(program, *controllers)
	}
	if controllers != nil && !done || p.Hosts == nil {
		return program, nil
	}
	units, err := p.Hosts(ctx)
	if err != nil || len(units) == 0 {
		return program, err
	}
	hosts, _, err := p.rollout(ctx, entityid.Derive(rollout.HostReleaseDomain, id), rollout.KindHost, units, desired)
	if err != nil {
		return nil, err
	}
	if hosts != nil {
		program = append(program, *hosts)
	}
	return program, nil
}

// rollout returns the generation's rollout of units: the stored one once it
// began (done when it completed), else one for the units that do not run
// the release yet, nil when there are none.
func (p ReleaseProgram) rollout(ctx context.Context, id string, kind rollout.Kind, units []rollout.Unit,
	desired rollout.Desired,
) (*rollout.Spec, bool, error) {
	existing, _, err := p.Store.Load(ctx, id)
	if err == nil {
		// The stored plan is this generation's step, whatever it ended as.
		spec := existingSpec(existing)
		return &spec, existing.Phase == rollout.PhaseComplete, nil
	}
	if !errors.Is(err, jetstream.ErrKeyNotFound) {
		return nil, false, err
	}
	behind, from, err := p.Behind(units, desired.Release.Digest)
	if err != nil || len(behind) == 0 {
		return nil, false, err
	}
	if bad, err := p.Store.IsKnownBad(ctx, desired.Release.Digest); err != nil || bad {
		return nil, false, err
	}
	return &rollout.Spec{RolloutID: id, Kind: kind, Cell: desired.Cell, FromDigest: from,
		ToDigest: desired.Release.Digest, Units: behind, Policy: p.Policy,
		StartedAt: desired.Release.CreatedAt}, false, nil
}

func existingSpec(record rollout.Record) rollout.Spec {
	units := make([]rollout.Unit, 0, len(record.Units))
	for id, progress := range record.Units {
		units = append(units, rollout.Unit{ID: id, Group: progress.Group, Seed: progress.Seed})
	}
	return rollout.Spec{RolloutID: record.RolloutID, Kind: record.Kind, Cell: record.Cell, FromDigest: record.FromDigest,
		ToDigest: record.ToDigest, Units: units, Policy: record.Policy, StartedAt: record.StartedAt}
}

// Behind returns the units that do not run target and the one release they
// all run. Every unit must have a fresh proof, so a step never starts while
// a peer is silent, and the units behind must agree on their release.
func (p ReleaseProgram) Behind(units []rollout.Unit, target string) ([]rollout.Unit, string, error) {
	now, freshness := time.Now().UTC(), p.Freshness
	if p.Now != nil {
		now = p.Now().UTC()
	}
	if freshness <= 0 {
		freshness = DefaultProofFreshness
	}
	var behind []rollout.Unit
	digest := ""
	for _, unit := range units {
		proof, ok := p.Proofs.Latest(unit.ID)
		if !ok || !isFresh(proof, now, freshness) {
			return nil, "", fmt.Errorf("unit %s has no fresh health proof", unit.ID)
		}
		if proof.BinarySHA256 == target {
			continue
		}
		if digest != "" && proof.BinarySHA256 != digest {
			return nil, "", fmt.Errorf("units run different releases (%s, %s)", short(digest), short(proof.BinarySHA256))
		}
		digest = proof.BinarySHA256
		behind = append(behind, unit)
	}
	return behind, digest, nil
}

executor_loop.text:
func (e *Executor) forget(rolloutID string) {
	e.rolloutID = rolloutID
	e.issued, e.holds, e.paged = map[string]*issue{}, map[string]string{}, map[string]bool{}
}

func (e *Executor) now() time.Time {
	if e.Now != nil {
		return e.Now().UTC()
	}
	return time.Now().UTC()
}

func (e *Executor) freshness() time.Duration {
	if e.ProofFreshness > 0 {
		return e.ProofFreshness
	}
	return DefaultProofFreshness
}

// Run drives the active rollout until ctx ends. Tick errors are logged and
// retried on the next tick: a rollout only ever waits, its deadlines decide.
func (e *Executor) Run(ctx context.Context) error {
	if e.Store == nil || e.Fencer == nil || e.Driver == nil || e.Proofs == nil {
		return fmt.Errorf("%w: rollout executor needs a store, fencer, driver and proof source", ErrInvalid)
	}
	interval := e.Interval
	if interval <= 0 {
		interval = DefaultInterval
	}
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for {
		ctx := observability.StartTrace(ctx)
		if err := e.Tick(ctx); err != nil && ctx.Err() == nil {
			slog.WarnContext(ctx, "rollout executor tick failed", "component", "rollout", "error", err)
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-ticker.C:
		case <-e.Wake:
		}
	}
}

// Tick runs one leader-only pass: adopt the active rollout under the
// current epoch, derive its next actions, perform them, and commit the
// events they produced. A follower forgets its leader-local memory.
func (e *Executor) Tick(ctx context.Context) error {
	snapshot := e.Fencer.Current()
	if !snapshot.CanMutate() {
		e.forget("")
		return nil
	}
	if e.issued == nil {
		e.forget("")
	}
	if err := e.Store.RecoverReservation(ctx, snapshot.Epoch); err != nil {
		return err
	}
	record, revision, ok, err := e.Store.Active(ctx)
	if err != nil {
		return err
	}
	if !ok {
		e.forget("")
		if err := e.startNext(ctx, snapshot.Epoch); err != nil {
			e.waiting = err.Error()
			e.publish(snapshot.Epoch, nil)
			return err
		}
		if record, revision, ok, err = e.Store.Active(ctx); err != nil || !ok {
			e.publish(snapshot.Epoch, nil)
			return err
		}
	}
	if record.RolloutID != e.rolloutID {
		e.forget(record.RolloutID)
	}
	if record.AuthorityEpoch != snapshot.Epoch && !record.Phase.Terminal() {
		id := record.RolloutID
		if record, revision, err = e.Store.Adopt(ctx, id, snapshot.Epoch); err != nil {
			return fmt.Errorf("adopt rollout %s: %w", id, err)
		}
	}
	if record.Phase.Terminal() {
		e.forget(record.RolloutID)
		e.publish(snapshot.Epoch, &record)
		return e.Store.Settle(ctx, record, snapshot.Epoch)
	}
	defer func() { e.publish(snapshot.Epoch, &record) }()
	for range maxRounds {
		before := revision
		if record.Phase == rollout.PhasePending {
			if err := e.apply(ctx, &record, &revision, rollout.Event{Kind: rollout.EventStart, At: e.now()}); err != nil {
				return err
			}
		}
		// Deadlines are committed before any effect is derived: a tick
		// that resumes after a deadline rolls back (or freezes) instead of
		// still sending the expired step.
		if err := e.apply(ctx, &record, &revision, rollout.Event{Kind: rollout.EventTick, At: e.now()}); err != nil {
			return err
		}
		if record.Phase.Terminal() {
			break
		}
		events, err := e.act(ctx, record)
		if err != nil {
			return err
		}
		for _, event := range events {
			if err := e.apply(ctx, &record, &revision, event); err != nil {
				return err
			}
		}
		if err := e.apply(ctx, &record, &revision, rollout.Event{Kind: rollout.EventTick, At: e.now()}); err != nil {
			return err
		}
		if revision == before || record.Phase.Terminal() {
			break
		}
	}
	return nil
}

// apply feeds one event to the transition core and commits a changed
// record. An event the core rejects (stale for the current phase, a
// replayed report) is dropped: it was derived from an older record.
func (e *Executor) apply(ctx context.Context, record *rollout.Record, revision *uint64, event rollout.Event) error {
	next, err := rollout.Apply(*record, event)
	if errors.Is(err, rollout.ErrInvalidTransition) || errors.Is(err, rollout.ErrInvalid) || errors.Is(err, rollout.ErrTerminal) {
		slog.DebugContext(ctx, "rollout event dropped", "component", "rollout", "rollout", record.RolloutID,
			"event", event.Kind, "unit", event.Unit, "error", err)
		return nil
	}
	if err != nil {
		return err
	}
	if same, err := sameRecord(*record, next); err != nil || same {
		return err
	}
	committed, err := e.Store.Commit(ctx, *revision, next)
	if committed == 0 {
		return fmt.Errorf("commit rollout %s: %w", record.RolloutID, err)
	}
	if err != nil {
		// The record is committed; the cell slot catches up on a later
		// commit or Settle.
		slog.WarnContext(ctx, "rollout cell slot update is pending", "component", "rollout", "rollout", record.RolloutID, "error", err)
	}
	*record, *revision = next, committed
	return nil
}

func sameRecord(a, b rollout.Record) (bool, error) {
	left, err := protocol.EncodeJSON(a)
	if err != nil {
		return false, err
	}
	right, err := protocol.EncodeJSON(b)
	if err != nil {
		return false, err
	}
	return bytes.Equal(left, right), nil
}

executor_effects.text:
func (e *Executor) act(ctx context.Context, record rollout.Record) ([]rollout.Event, error) {
	var events []rollout.Event
	// A wave is promoted from stored reports when its last unit reports;
	// while a unit that already reported has lost its fresh proof, no
	// healthy report may complete the wave around it.
	lost := e.waveLostProof(record)
	// A unit that restarted during its soak is reported before any other
	// unit can complete the wave from the restarted unit's stored reports.
	if restart := e.waveRestart(record); restart != nil {
		return []rollout.Event{*restart}, nil
	}
	// A unit an earlier wave promoted that now proves another release
	// rolls the rollout back before any later wave moves or completes.
	if regressed := e.promotedRegression(record); regressed != nil {
		return []rollout.Event{*regressed}, nil
	}
	for _, action := range rollout.NextActions(record) {
		var event *rollout.Event
		var err error
		switch action.Kind {
		case rollout.ActionPreflight:
			event = e.preflight(ctx, record)
		case rollout.ActionPrepare:
			event, err = e.prepare(ctx, record, action)
		case rollout.ActionAwaitHealth:
			event = e.awaitHealth(record, action)
			if event != nil && event.Kind == rollout.EventHealthy && lost != "" {
				e.hold(record, "soak", "unit "+lost+" stopped proving it serves the target")
				event = nil
			} else if event != nil && event.Kind == rollout.EventHealthy {
				e.release(record, "soak")
			}
		case rollout.ActionRollback:
			event, err = e.rollback(ctx, record, action)
		case rollout.ActionPage:
			e.page(record)
		}
		if err != nil {
			// Events observed before the fence failed are dropped with
			// it: the successor derives them again.
			return nil, err
		}
		if event != nil {
			events = append(events, *event)
		}
	}
	return events, nil
}

func (e *Executor) preflight(ctx context.Context, record rollout.Record) *rollout.Event {
	if reason := e.checkGate(ctx, record, ""); reason != "" {
		e.hold(record, "", reason)
		return nil
	}
	now := e.now()
	for _, unit := range sortedUnits(record) {
		proof, ok := e.Proofs.Latest(unit)
		if !ok || !e.fresh(proof) {
			e.hold(record, "", "unit "+unit+" has no fresh health proof")
			return nil
		}
		if proof.BinarySHA256 != record.FromDigest {
			e.release(record, "")
			return &rollout.Event{Kind: rollout.EventPreflightFailed, At: now,
				Reason: fmt.Sprintf("unit %s serves %s, not the rollout's from digest", unit, short(proof.BinarySHA256))}
		}
	}
	e.release(record, "")
	return &rollout.Event{Kind: rollout.EventPreflightPassed, At: now}
}

func (e *Executor) prepare(ctx context.Context, record rollout.Record, action rollout.Action) (*rollout.Event, error) {
	if reason := e.peersServing(ctx, record, action.Peers); reason != "" {
		e.hold(record, action.Unit, reason)
		return nil, nil
	}
	if reason := e.checkGate(ctx, record, action.Unit); reason != "" {
		e.hold(record, action.Unit, reason)
		return nil, nil
	}
	if e.expired(action) {
		return nil, nil
	}
	if err := e.fence(ctx, record); err != nil {
		return nil, err
	}
	step := e.track(stepKey(record.RolloutID, action.Unit, StepPrepare), action.Unit)
	if !step.accepted {
		// Each attempt until one is accepted re-reads the unit's
		// incarnation: a restart between an undelivered attempt and the
		// accepted one was not caused by the step and must not count as
		// the unit coming back on the wrong binary.
		step.before, step.known = e.Proofs.Latest(action.Unit)
		step.at = e.now()
	}
	reply, err := e.Driver.Step(ctx, Step{RolloutID: record.RolloutID, Kind: record.Kind, Unit: action.Unit,
		OperationID: action.OperationID, Action: StepPrepare, Digest: action.Digest, Replaces: record.FromDigest,
		Epoch:       record.AuthorityEpoch,
		ProofWindow: time.Duration(record.Policy.ProofDeadlineSeconds) * time.Second,
		Deadline:    action.Deadline,
		Fence:       func(ctx context.Context) error { return e.fence(ctx, record) }})
	switch {
	case errors.Is(err, ErrLeaseLost):
		return nil, err
	case err != nil:
		slog.WarnContext(ctx, "rollout step was not delivered", "component", "rollout", "rollout", record.RolloutID,
			"unit", action.Unit, "error", err)
		e.hold(record, action.Unit, "the unit's step agent did not answer")
		return nil, nil
	case reply.Outcome.Accepted():
		e.release(record, action.Unit)
		if !step.accepted {
			step.accepted = true
			recordStep(record, action.Unit, StepPrepare, reply.Outcome)
		}
		return &rollout.Event{Kind: rollout.EventPrepared, Unit: action.Unit, At: e.now()}, nil
	case reply.Outcome == OutcomeRefused:
		e.release(record, action.Unit)
		return &rollout.Event{Kind: rollout.EventHeld, Unit: action.Unit, At: e.now(),
			Reason: "unit " + action.Unit + " refused the step: " + reply.Reason}, nil
	default:
		e.hold(record, action.Unit, "the unit asked to retry: "+reply.Reason)
		return nil, nil
	}
}

func (e *Executor) awaitHealth(record rollout.Record, action rollout.Action) *rollout.Event {
	proof, ok := e.Proofs.Latest(action.Unit)
	key := stepKey(record.RolloutID, action.Unit, StepPrepare)
	if _, remembered := e.issued[key]; !remembered && ok {
		// A successor leader, which never saw the step, takes the first
		// incarnation it sees as the baseline: a later incarnation on
		// another release is the unit coming back on the wrong binary.
		// When that first incarnation already is one, the proof deadline
		// still rolls the rollout back.
		e.issued[key] = &issue{at: e.now(), before: proof, known: true, accepted: true}
	}
	// Only a fresh proof completes anything: a cached one cannot supply a
	// soak report for a unit that has since stopped serving.
	if !ok || proof.seen().Before(record.PhaseStartedAt) || !e.fresh(proof) {
		return nil
	}
	if proof.BinarySHA256 == record.ToDigest {
		progress := record.Units[action.Unit]
		if progress.HealthyReports > 0 && !proof.seen().After(progress.LastHealthyAt) {
			return nil
		}
		return &rollout.Event{Kind: rollout.EventHealthy, Unit: action.Unit, Health: proof.Health(), At: e.now()}
	}
	// A new incarnation that serves another release after the step means
	// the unit came back on the wrong binary (for example the watchdog
	// rolled it back). The old process's proofs, sent before it restarted,
	// are ignored by the incarnation check.
	step, known := e.issued[key]
	if known && step.known && !proof.sameIncarnation(step.before) && proof.arrivedAfter(step.at) {
		return &rollout.Event{Kind: rollout.EventUnhealthy, Unit: action.Unit, At: e.now(),
			Reason: fmt.Sprintf("unit %s restarted serving %s instead of the target", action.Unit, short(proof.BinarySHA256))}
	}
	return nil
}

func (e *Executor) rollback(ctx context.Context, record rollout.Record, action rollout.Action) (*rollout.Event, error) {
	key := stepKey(record.RolloutID, action.Unit, StepRollback) + "/" + action.OperationID
	step, sent := e.issued[key]
	if !sent || !step.accepted {
		if reason := e.peersServing(ctx, record, action.Peers); reason != "" {
			e.hold(record, action.Unit, reason)
			return nil, nil
		}
		if reason := e.checkGate(ctx, record, action.Unit); reason != "" {
			e.hold(record, action.Unit, reason)
			return nil, nil
		}
		if e.expired(action) {
			return nil, nil
		}
		if err := e.fence(ctx, record); err != nil {
			return nil, err
		}
		step = e.track(key, action.Unit)
		reply, err := e.Driver.Step(ctx, Step{RolloutID: record.RolloutID, Kind: record.Kind, Unit: action.Unit,
			OperationID: action.OperationID, Action: StepRollback, Digest: action.Digest, Replaces: record.ToDigest,
			Epoch: record.AuthorityEpoch, ProofWindow: time.Duration(record.Policy.RollbackDeadlineSeconds) * time.Second,
			Deadline: action.Deadline,
			Fence:    func(ctx context.Context) error { return e.fence(ctx, record) }})
		switch {
		case errors.Is(err, ErrLeaseLost):
			return nil, err
		case err != nil:
			slog.WarnContext(ctx, "rollout rollback step was not delivered", "component", "rollout", "rollout", record.RolloutID,
				"unit", action.Unit, "error", err)
			e.hold(record, action.Unit, "the unit's step agent did not answer")
			return nil, nil
		case reply.Outcome == OutcomeRefused:
			e.release(record, action.Unit)
			return &rollout.Event{Kind: rollout.EventRollbackHeld, Unit: action.Unit, At: e.now(),
				Reason: "unit " + action.Unit + " refused its rollback: " + reply.Reason}, nil
		case !reply.Outcome.Accepted():
			e.hold(record, action.Unit, "the unit asked to retry its rollback: "+reply.Reason)
			return nil, nil
		}
		e.release(record, action.Unit)
		step.accepted = true
		// Only a proof observed after the accepted attempt returned speaks
		// for the process it left running; a proof cached from an earlier,
		// failed attempt does not.
		step.at = e.now()
		recordStep(record, action.Unit, StepRollback, reply.Outcome)
	}
	proof, ok := e.Proofs.Latest(action.Unit)
	if ok && proof.BinarySHA256 == record.FromDigest && proof.arrivedAfter(step.at) && e.fresh(proof) {
		return &rollout.Event{Kind: rollout.EventRollbackServing, Unit: action.Unit, At: e.now()}, nil
	}
	return nil, nil
}

executor_guards.text:
func (e *Executor) fence(ctx context.Context, record rollout.Record) error {
	if err := e.Fencer.Guard(ctx, record.AuthorityEpoch); err != nil {
		return fmt.Errorf("%w: %w", ErrLeaseLost, err)
	}
	return nil
}

// ErrLeaseLost stops a tick whose authority lease was lost before a step
// left the leader.
var ErrLeaseLost = errors.New("authority lease lost before a rollout step")

// waveLostProof names a unit that already proved the target, a soaking
// unit of the current wave that reported healthy or a unit an earlier wave
// promoted, but has no fresh proof on the target now. While one exists no
// healthy report completes a wave, so neither a later wave nor the whole
// rollout completes around a unit that stopped serving; the phase deadline
// decides when that becomes a rollback.
func (e *Executor) waveLostProof(record rollout.Record) string {
	if record.WaveIndex < 0 || record.WaveIndex >= len(record.Waves) {
		return ""
	}
	for _, id := range sortedUnits(record) {
		progress := record.Units[id]
		if progress.State != rollout.UnitPromoted && (progress.State != rollout.UnitSoaking || progress.HealthyReports == 0) {
			continue
		}
		if proof, ok := e.Proofs.Latest(id); !ok || !e.fresh(proof) || proof.BinarySHA256 != record.ToDigest {
			return id
		}
	}
	return ""
}

// waveRestart returns the healthy report of a soaking unit of the current
// wave whose fresh proof comes from a new incarnation; the transition core
// rolls the rollout back on it.
func (e *Executor) waveRestart(record rollout.Record) *rollout.Event {
	if !forwardPhase(record.Phase) {
		return nil
	}
	for _, id := range record.Waves[record.WaveIndex] {
		progress := record.Units[id]
		if progress.State != rollout.UnitSoaking || progress.HealthyReports == 0 {
			continue
		}
		proof, ok := e.Proofs.Latest(id)
		if ok && e.fresh(proof) && !proof.seen().Before(record.PhaseStartedAt) &&
			(proof.ProcessID != progress.ProcessID || proof.StartNonce != progress.StartNonce) {
			return &rollout.Event{Kind: rollout.EventHealthy, Unit: id, Health: proof.Health(), At: e.now()}
		}
	}
	return nil
}

// promotedRegression reports an unhealthy event for a unit that an earlier
// wave promoted but whose fresh proof, newer than its last healthy report,
// serves another release than the target. A unit without a fresh proof is
// judged by the peer checks of the steps around it instead.
func (e *Executor) promotedRegression(record rollout.Record) *rollout.Event {
	if !forwardPhase(record.Phase) {
		return nil
	}
	for _, id := range sortedUnits(record) {
		progress := record.Units[id]
		if progress.State != rollout.UnitPromoted {
			continue
		}
		proof, ok := e.Proofs.Latest(id)
		if ok && e.fresh(proof) && proof.seen().After(progress.LastHealthyAt) && proof.BinarySHA256 != record.ToDigest {
			return &rollout.Event{Kind: rollout.EventUnhealthy, Unit: id, At: e.now(),
				Reason: fmt.Sprintf("promoted unit %s now serves %s instead of the target", id, short(proof.BinarySHA256))}
		}
	}
	return nil
}

func forwardPhase(phase rollout.Phase) bool {
	return phase == rollout.PhaseCanary || phase == rollout.PhaseCanarySoak ||
		phase == rollout.PhaseBatch || phase == rollout.PhaseBatchSoak
}

// expired reports a step whose phase deadline passed while its gates ran;
// the next tick commits the deadline instead of sending it.
func (e *Executor) expired(action rollout.Action) bool {
	return !action.Deadline.IsZero() && !e.now().Before(action.Deadline)
}

// fresh requires the proof to have reached the leader within the
// freshness limit, on the leader's clock, and its signed observation time
// to be no older than that limit plus the verified clock skew, so neither
// a unit clock behind the leader's nor a late delivery of an old proof
// decides it.
func (e *Executor) fresh(proof HealthProof) bool { return isFresh(proof, e.now(), e.freshness()) }

func isFresh(proof HealthProof, now time.Time, freshness time.Duration) bool {
	return now.Sub(proof.seen()) <= freshness && now.Sub(proof.ObservedAt) <= freshness+healthClockSkew
}

func (e *Executor) page(record rollout.Record) {
	if e.paged[record.RolloutID] {
		return
	}
	e.paged[record.RolloutID] = true
	slog.Error("rollout is frozen and needs an operator", "component", "rollout", "rollout", record.RolloutID,
		"kind", record.Kind, "reason", record.Reason)
}

// track returns the leader-local memory of a step, creating it with the
// unit's proof from before the step.
func (e *Executor) track(key, unit string) *issue {
	if step, exists := e.issued[key]; exists {
		return step
	}
	before, known := e.Proofs.Latest(unit)
	step := &issue{at: e.now(), before: before, known: known}
	e.issued[key] = step
	return step
}

func stepKey(rolloutID, unit string, action StepAction) string {
	return rolloutID + "/" + unit + "/" + string(action)
}

// peersServing requires a fresh proof from every group peer, on either
// side of the rollout, so a step never takes a second replica down. A peer
// the rollout does not step (pending or rolled back) may serve a third
// release an operator installed by hand, unless the cell knows it bad.
func (e *Executor) peersServing(ctx context.Context, record rollout.Record, peers []string) string {
	for _, peer := range peers {
		proof, ok := e.Proofs.Latest(peer)
		if !ok || !e.fresh(proof) {
			return "group peer " + peer + " is not serving"
		}
		digest := proof.BinarySHA256
		if digest == record.FromDigest || digest == record.ToDigest {
			continue
		}
		state := record.Units[peer].State
		if state != rollout.UnitPending && state != rollout.UnitRolledBack || slices.Contains(record.KnownBad, digest) {
			return "group peer " + peer + " is not serving"
		}
		// The record keeps a bounded list; the store has every rejected
		// digest. A failed read holds the step.
		if bad, err := e.Store.IsKnownBad(ctx, digest); err != nil || bad {
			return "group peer " + peer + " serves a release the cell may know bad"
		}
	}
	return ""
}

func (e *Executor) checkGate(ctx context.Context, record rollout.Record, unit string) string {
	if e.Gate == nil {
		return ""
	}
	if err := e.Gate.Check(ctx, record, unit); err != nil {
		return err.Error()
	}
	return ""
}

// startNext begins the first program rollout that has not completed. A
// program stops at a rollout that ended any other way.
func (e *Executor) startNext(ctx context.Context, epoch uint64) error {
	e.waiting = ""
	if e.Program == nil {
		return nil
	}
	program, err := e.Program(ctx)
	if err != nil {
		return fmt.Errorf("read rollout program: %w", err)
	}
	for _, spec := range program {
		existing, _, err := e.Store.Load(ctx, spec.RolloutID)
		if errors.Is(err, jetstream.ErrKeyNotFound) {
			now := e.now()
			if spec.StartedAt.After(now) {
				e.waiting = fmt.Sprintf("the release is issued at %s; waiting for the cell clock", spec.StartedAt)
				return nil
			}
			spec.AuthorityEpoch = epoch
			if _, _, err := e.Store.Begin(ctx, spec, now); err != nil {
				return fmt.Errorf("begin rollout %s: %w", spec.RolloutID, err)
			}
			return nil
		}
		if err != nil {
			return e.halt(spec.RolloutID, err.Error())
		}
		// A completed record only satisfies the program step it was
		// planned from: the same ID with another target, kind, waves or
		// policy stops the program instead of skipping ahead.
		if err := existing.Matches(spec); err != nil {
			return e.halt(spec.RolloutID, err.Error())
		}
		if existing.Phase != rollout.PhaseComplete {
			return e.halt(spec.RolloutID, "rollout ended "+string(existing.Phase))
		}
	}
	return nil
}

func (e *Executor) halt(rolloutID, reason string) error {
	e.waiting = "rollout " + rolloutID + " stopped the program: " + reason
	if e.halted != rolloutID {
		e.halted = rolloutID
		slog.Warn("rollout program stopped", "component", "rollout", "rollout", rolloutID, "reason", reason)
	}
	return nil
}

func (e *Executor) publish(epoch uint64, record *rollout.Record) {
	if e.Status == nil {
		return
	}
	status := statusOf(e.Cell, epoch, record, e.Proofs, e.holds, e.now())
	if record == nil {
		status.Waiting = e.waiting
	}
	e.Status.PublishStatus(status)
}

func sortedUnits(record rollout.Record) []string {
	var units []string
	for _, wave := range record.Waves {
		units = append(units, wave...)
	}
	return units
}

func short(digest string) string {
	if len(digest) > 12 {
		return digest[:12]
	}
	return digest
}

proof_clock.text:
const (
	HealthDomain = "terrascale.orchestrator.rollout-health"
	HealthSchema = "terrascale.orchestrator.rollout-health.v1"
	// HealthLifetime bounds one proof, so only a recent one counts.
	HealthLifetime = 2 * time.Minute
	// DefaultProofInterval is how often a healthy unit publishes a proof.
	DefaultProofInterval = 5 * time.Second
	healthClockSkew      = time.Minute
	// incarnationQuiet is how long a unit's newest incarnation must have
	// been silent before a new incarnation whose clock reads earlier
	// replaces it: a live incarnation keeps proving within it, so a
	// delayed proof of a superseded process never displaces it.
	incarnationQuiet = 2 * DefaultProofInterval
	maxProofUnits    = 4 * rollout.MaxUnits
	// maxRetired bounds the superseded incarnations kept per unit.
	maxRetired = 8
	// retiredFor is how long a superseded incarnation stays refused: no
	// proof it signed can still verify after that.
	retiredFor = HealthLifetime + healthClockSkew
)

var (
	ErrInvalid = errors.New("rollout executor input is invalid")

	unitRE   = regexp.MustCompile(`^[a-z0-9][a-z0-9_.-]{0,127}$`)
	nonceRE  = regexp.MustCompile(`^[0-9a-f]{32}$`)
	digestRE = regexp.MustCompile(`^[0-9a-f]{64}$`)
)

// HealthProof is signed by a running unit while it is healthy. It names the
// exact binary digest the process executes and its incarnation (process ID
// and a per-start nonce), so the executor detects both a wrong release and
// a restart during soak.
type HealthProof struct {
	Schema       string    `json:"schema"`
	Cell         string    `json:"cell"`
	Unit         string    `json:"unit"`
	BinarySHA256 string    `json:"binary_sha256"`
	ProcessID    int64     `json:"process_id"`
	StartNonce   string    `json:"start_nonce"`
	ObservedAt   time.Time `json:"observed_at"`
	// ReceivedAt is when the collector accepted the proof, on the leader's
	// own clock. It is never signed or sent; it orders a proof against the
	// leader's steps without trusting the unit's clock.
	ReceivedAt time.Time `json:"-"`
}

func (proof HealthProof) validate() error {
	if proof.Schema != HealthSchema || !unitRE.MatchString(proof.Cell) || !unitRE.MatchString(proof.Unit) ||
		!digestRE.MatchString(proof.BinarySHA256) || proof.ProcessID <= 0 || !nonceRE.MatchString(proof.StartNonce) ||
		proof.ObservedAt.IsZero() {
		return fmt.Errorf("%w: health proof", ErrInvalid)
	}
	return nil
}

// Health converts the proof into the rollout core's health observation.
// Its ObservedAt is the leader's receipt time (seen), so the core orders
// the report against the leader-clock phase and soak times without
// trusting the unit's clock; the signed ObservedAt only bounds replay.
func (proof HealthProof) Health() rollout.Health {
	return rollout.Health{Digest: proof.BinarySHA256, ProcessID: proof.ProcessID, StartNonce: proof.StartNonce,
		ObservedAt: proof.seen()}
}

// seen is when the proof reached the leader, on the leader's clock. A
// source that does not record receipt falls back to the unit's own
// observation time.
func (proof HealthProof) seen() time.Time {
	if !proof.ReceivedAt.IsZero() {
		return proof.ReceivedAt
	}
	return proof.ObservedAt
}

// arrivedAfter reports whether the proof reached the leader after at, a
// leader-clock time.
func (proof HealthProof) arrivedAfter(at time.Time) bool {
	return proof.seen().After(at)
}

func (proof HealthProof) sameIncarnation(other HealthProof) bool {
	return proof.ProcessID == other.ProcessID && proof.StartNonce == other.StartNonce
}

step_accepted.text:
func (outcome StepOutcome) Accepted() bool {
	return outcome == OutcomeActivated || outcome == OutcomePending || outcome == OutcomeCurrent
}

operator.text:
func Abort(ctx context.Context, store *rollout.Store, epoch uint64, digest, reason string, now time.Time) (string, error) {
	return operate(ctx, store, epoch, func(record rollout.Record) (rollout.Event, bool, error) {
		return rollout.Event{Kind: rollout.EventAbort, Reason: reason, At: now}, record.ToDigest != digest, nil
	})
}

// Resume retries the rollback of a frozen rollout (rollout.EventResume); it
// never moves a unit towards the rejected target. A unit whose fresh proof
// names a third release, neither the rollback's nor the target nor known
// bad, was moved off the target by an operator and is not stepped back. It
// returns the ID of the rollout it resumed, if any.
func Resume(ctx context.Context, store *rollout.Store, proofs ProofSource, epoch uint64, now time.Time) (string, error) {
	return operate(ctx, store, epoch, func(record rollout.Record) (rollout.Event, bool, error) {
		var left []string
		for id := range record.Units {
			if proofs == nil {
				break
			}
			proof, ok := proofs.Latest(id)
			digest := proof.BinarySHA256
			if !ok || !isFresh(proof, now, DefaultProofFreshness) || digest == record.FromDigest ||
				digest == record.ToDigest || slices.Contains(record.KnownBad, digest) {
				continue
			}
			// The record keeps a bounded list; the store has every
			// rejected digest.
			if bad, err := store.IsKnownBad(ctx, digest); err != nil {
				return rollout.Event{}, false, err
			} else if !bad {
				left = append(left, id)
			}
		}
		slices.Sort(left)
		return rollout.Event{Kind: rollout.EventResume, At: now, Left: left}, record.Phase == rollout.PhaseFrozen, nil
	})
}

// operate commits one operator event to the active rollout, adopting it
// under epoch first. The executor commits by CAS too, so a conflict with
// its tick is retried on the fresh record.
func operate(ctx context.Context, store *rollout.Store, epoch uint64,
	event func(rollout.Record) (rollout.Event, bool, error),
) (string, error) {
	for range 4 {
		record, revision, ok, err := store.Active(ctx)
		if err != nil || !ok || record.Phase.Terminal() {
			return "", err
		}
		if record.AuthorityEpoch != epoch {
			if record, revision, err = store.Adopt(ctx, record.RolloutID, epoch); err != nil {
				if errors.Is(err, rollout.ErrConflict) {
					continue
				}
				return "", err
			}
		}
		next, apply, err := event(record)
		if err != nil || !apply {
			return "", err
		}
		updated, err := rollout.Apply(record, next)
		if errors.Is(err, rollout.ErrInvalidTransition) || errors.Is(err, rollout.ErrTerminal) {
			return "", nil
		}
		if err != nil {
			return "", err
		}
		committed, err := store.Commit(ctx, revision, updated)
		if errors.Is(err, rollout.ErrConflict) {
			continue
		}
		if committed == 0 {
			return "", err
		}
		// A committed record whose cell slot update is pending is settled
		// by the executor's next tick.
		return record.RolloutID, nil
	}
	return "", rollout.ErrConflict
}

status.text:
func statusOf(cell string, epoch uint64, record *rollout.Record, proofs ProofSource, holds map[string]string,
	now time.Time,
) Status {
	status := Status{Schema: StatusSchema, Cell: cell, Epoch: epoch, UpdatedAt: now.UTC()}
	if record == nil {
		return status
	}
	status.Active = record.Phase.Active()
	status.RolloutID, status.Kind, status.Phase = record.RolloutID, record.Kind, record.Phase
	status.Wave, status.Waves = record.WaveIndex+1, len(record.Waves)
	status.FromDigest, status.ToDigest, status.Reason = record.FromDigest, record.ToDigest, record.Reason
	status.PhaseDeadline = record.PhaseDeadline
	if len(holds) > 0 {
		status.Holds = make(map[string]string, len(holds))
		for unit, reason := range holds {
			status.Holds[unit] = reason
		}
	}
	for id, progress := range record.Units {
		unit := UnitStatus{ID: id, Group: progress.Group, Seed: progress.Seed, Wave: progress.Wave, State: progress.State}
		if proofs != nil {
			if proof, ok := proofs.Latest(id); ok {
				unit.Digest, unit.ProofAt = proof.BinarySHA256, proof.ObservedAt
			}
		}
		status.Units = append(status.Units, unit)
	}
	slices.SortFunc(status.Units, func(a, b UnitStatus) int {
		if a.Wave != b.Wave {
			return a.Wave - b.Wave
		}
		if a.ID < b.ID {
			return -1
		}
		if a.ID > b.ID {
			return 1
		}
		return 0
	})
	return status
}

executor_decisions.text:
func unitSubject(record rollout.Record, unit string) decisionlog.Subject {
	return decisionlog.Subject{Kind: "member", ID: unit, Name: string(record.Kind) + "/" + record.RolloutID}
}

func holdKey(unit string) string {
	if unit == "" {
		return "preflight"
	}
	return unit
}

// hold records that a step for unit ("" is preflight) waits on reason.
func (e *Executor) hold(record rollout.Record, unit, reason string) {
	key := holdKey(unit)
	if e.holds[key] == reason {
		return
	}
	e.holds[key] = reason
	decisionlog.Record(context.Background(), decisionlog.Decision{
		Region:   record.Cell,
		Actor:    decisionlog.Actor{Slice: "rollout"},
		Kind:     decisionlog.KindHeld,
		Subject:  unitSubject(record, key),
		Summary:  "Held the " + string(record.Phase) + " step of " + key + " in rollout " + record.RolloutID,
		Reason:   reason,
		Rule:     "rollout.executor.gate",
		Status:   decisionlog.StatusPending,
		Epoch:    record.AuthorityEpoch,
		ParentID: decisionlog.Correlated(rollout.ReleaseCorrelation(record.ToDigest)),
		Attrs:    map[string]string{"rollout": record.RolloutID, "phase": string(record.Phase)},
	})
	slog.Info("rollout step held", "component", "rollout", "rollout", record.RolloutID, "unit", key, "reason", reason)
}

// release clears a hold of unit once its step proceeds.
func (e *Executor) release(record rollout.Record, unit string) {
	key := holdKey(unit)
	if _, held := e.holds[key]; !held {
		return
	}
	delete(e.holds, key)
	decisionlog.Record(context.Background(), decisionlog.Decision{
		Region:   record.Cell,
		Actor:    decisionlog.Actor{Slice: "rollout"},
		Kind:     decisionlog.KindHoldCleared,
		Subject:  unitSubject(record, key),
		Summary:  "Released the " + string(record.Phase) + " step of " + key + " in rollout " + record.RolloutID,
		Reason:   "Its gate and group peers are healthy again.",
		Rule:     "rollout.executor.gate",
		Status:   decisionlog.StatusSucceeded,
		Epoch:    record.AuthorityEpoch,
		ParentID: decisionlog.Correlated(rollout.ReleaseCorrelation(record.ToDigest)),
		Attrs:    map[string]string{"rollout": record.RolloutID, "phase": string(record.Phase)},
	})
}

// recordStep journals a unit step the unit's agent accepted.
func recordStep(record rollout.Record, unit string, action StepAction, outcome StepOutcome) {
	kind, summary, digest := decisionlog.KindStageChanged, "Moved "+unit+" to the target release", record.ToDigest
	if action == StepRollback {
		kind, summary, digest = decisionlog.KindRollback, "Returned "+unit+" to the previous release", record.FromDigest
	}
	decisionlog.Record(context.Background(), decisionlog.Decision{
		Region:   record.Cell,
		Actor:    decisionlog.Actor{Slice: "rollout"},
		Kind:     kind,
		Subject:  unitSubject(record, unit),
		Summary:  summary + " in rollout " + record.RolloutID,
		Reason:   "The unit's group peers were serving and the cluster gate passed.",
		Rule:     "rollout.executor." + string(action),
		Status:   decisionlog.StatusInProgress,
		Epoch:    record.AuthorityEpoch,
		ParentID: decisionlog.Correlated(rollout.ReleaseCorrelation(record.ToDigest)),
		Attrs: map[string]string{"rollout": record.RolloutID, "digest": digest, "outcome": string(outcome),
			"phase": string(record.Phase)},
	})
}

