func (state CellState) validate(cell string) error {
	if state.SchemaVersion != SchemaVersion || state.Cell != cell ||
		state.ActiveRolloutID != "" && !entityid.Valid(state.ActiveRolloutID) ||
		len(state.KnownBad) > MaxKnownBad || len(state.Attempts) > maxAttemptDigest {
		return fmt.Errorf("%w: cell rollout state", ErrInvalid)
	}
	for _, digest := range state.KnownBad {
		if !digestRE.MatchString(digest) {
			return fmt.Errorf("%w: known-bad digest", ErrInvalid)
		}
	}
	return nil
}

// Store persists rollout records with CAS on the KV revision. Every write is
// preceded by an authority Guard for the record's epoch (invariant b).
// Records decode tolerantly, so an older controller reads a newer one's
// records during a self-update; schema_version names breaking changes.
type Store struct {
	// Admission and publication share the lifetime of a reservation's generation proof.
	mu     sync.Mutex
	kv     jetstream.KeyValue
	fencer authority.Fencer
	cell   string
}

// OpenStore provisions or binds the rollout bucket for one cell.
func OpenStore(ctx context.Context, js jetstream.JetStream, cell string, replicas int, fencer authority.Fencer) (*Store, error) {
	if js == nil || fencer == nil || !tokenRE.MatchString(cell) || replicas != 1 && replicas != 3 && replicas != 5 {
		return nil, fmt.Errorf("%w: rollout store configuration", ErrInvalid)
	}
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket: Bucket, Storage: jetstream.FileStorage, Replicas: replicas, History: 8, MaxValueSize: maxRecordBytes,
	})
	if err != nil {
		return nil, fmt.Errorf("rollout store: %w", err)
	}
	return &Store{kv: kv, fencer: fencer, cell: cell}, nil
}

func rolloutKey(id string) string { return id }

// knownBadKey holds one durable known-bad record. The cell's KnownBad list is
// bounded and ages out its oldest entries; these per-digest records do not,
// so a rejected digest never becomes eligible again without a reviewed
// removal of its record.
func knownBadKey(digest string) string { return "knownbad." + digest }

type knownBadEntry struct {
	Digest string `json:"digest"`
}

// recordKnownBad durably records digest. It is idempotent.
func (s *Store) recordKnownBad(ctx context.Context, epoch uint64, digest string) error {
	if !digestRE.MatchString(digest) {
		return fmt.Errorf("%w: known-bad digest", ErrInvalid)
	}
	encoded, err := protocol.EncodeJSON(knownBadEntry{Digest: digest})
	if err != nil {
		return err
	}
	if err := s.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	if _, err := s.kv.Create(ctx, knownBadKey(digest), encoded); err != nil && !errors.Is(err, jetstream.ErrKeyExists) {
		return fmt.Errorf("record known-bad digest: %w", err)
	}
	return nil
}

// knownBad reports whether digest is known bad in the cell list or in its
// durable per-digest record.
func (s *Store) knownBad(ctx context.Context, state CellState, digest string) (bool, error) {
	if slices.Contains(state.KnownBad, digest) {
		return true, nil
	}
	_, err := s.kv.Get(ctx, knownBadKey(digest))
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return false, nil
	}
	if err != nil {
		return false, fmt.Errorf("read known-bad digest: %w", err)
	}
	return true, nil
}

// Cell returns the cell slot and its revision (zero when absent).
func (s *Store) Cell(ctx context.Context) (CellState, uint64, error) {
	entry, err := s.kv.Get(ctx, cellKey)
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return CellState{SchemaVersion: SchemaVersion, Cell: s.cell}, 0, nil
	}
	if err != nil {
		return CellState{}, 0, err
	}
	var state CellState
	if err := protocol.DecodeTolerant(entry.Value(), &state, maxRecordBytes); err != nil {
		return CellState{}, 0, err
	}
	if err := state.validate(s.cell); err != nil {
		return CellState{}, 0, err
	}
	return state, entry.Revision(), nil
}

// Load returns a rollout record and its KV revision.
func (s *Store) Load(ctx context.Context, rolloutID string) (Record, uint64, error) {
	if !entityid.Valid(rolloutID) {
		return Record{}, 0, fmt.Errorf("%w: rollout ID", ErrInvalid)
	}
	entry, err := s.kv.Get(ctx, rolloutKey(rolloutID))
	if err != nil {
		return Record{}, 0, err
	}
	// Records decode tolerantly, so a marker would decode as an empty record:
	// read it first. A record always has a schema version and a marker never
	// does, so a newer binary's members change neither.
	if marker, err := decodeAbandoned(entry.Value(), rolloutID); err != nil {
		return Record{}, 0, err
	} else if marker != nil {
		return Record{}, 0, marker
	}
	var record Record
	if err := protocol.DecodeTolerant(entry.Value(), &record, maxRecordBytes); err != nil {
		return Record{}, 0, err
	}
	if err := record.Validate(); err != nil {
		return Record{}, 0, err
	}
	if record.Cell != s.cell || record.RolloutID != rolloutID {
		return Record{}, 0, fmt.Errorf("%w: stored rollout scope", ErrInvalid)
	}
	return record, entry.Revision(), nil
}

store_admission.text:
func (s *Store) Begin(ctx context.Context, spec Spec, now time.Time) (Record, uint64, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if spec.Cell != s.cell {
		return Record{}, 0, fmt.Errorf("%w: rollout cell", ErrInvalid)
	}
	if err := s.fencer.Guard(ctx, spec.AuthorityEpoch); err != nil {
		return Record{}, 0, err
	}
	// An ID already bound to another rollout is refused before the cell
	// slot is reserved or the target's attempt is counted.
	bound := false
	if existing, _, err := s.Load(ctx, spec.RolloutID); err == nil {
		if err := sameRollout(existing, spec); err != nil {
			return Record{}, 0, err
		}
		bound = true
	} else if errors.Is(err, ErrAbandonedRollout) {
		if err := s.releaseSlot(ctx, spec.AuthorityEpoch, spec.RolloutID); err != nil {
			return Record{}, 0, err
		}
		return Record{}, 0, ErrAbandonedRollout
	} else if !errors.Is(err, jetstream.ErrKeyNotFound) {
		return Record{}, 0, err
	}
	if !bound {
		if release, kind, found, err := s.releaseStage(ctx, spec.RolloutID); err != nil {
			return Record{}, 0, err
		} else if found && (spec.ToDigest != release.Digest || spec.Kind != kind ||
			!spec.StartedAt.IsZero() && !spec.StartedAt.Equal(release.CreatedAt)) {
			return Record{}, 0, fmt.Errorf("%w: release stage binding", ErrConflict)
		} else if found {
			spec.StartedAt = release.CreatedAt
			bound = true
		}
	}
	for range cellCASAttempts {
		state, revision, err := s.Cell(ctx)
		if err != nil {
			return Record{}, 0, err
		}
		if state.ActiveRolloutID == spec.RolloutID {
			// Only an existing immutable record can resume the same ID.
			if _, _, err := s.Load(ctx, spec.RolloutID); errors.Is(err, jetstream.ErrKeyNotFound) || errors.Is(err, ErrAbandonedRollout) {
				if err := s.abandon(ctx, spec.AuthorityEpoch, spec.RolloutID); err != nil {
					return Record{}, 0, err
				}
				if err := s.releaseSlot(ctx, spec.AuthorityEpoch, spec.RolloutID); err != nil {
					return Record{}, 0, err
				}
				return Record{}, 0, ErrAbandonedRollout
			} else if err != nil {
				return Record{}, 0, err
			}
			return s.createRecord(ctx, spec, state, now)
		}
		if state.ActiveRolloutID != "" {
			// A terminal commit whose cell release was interrupted is
			// repaired here; a live rollout keeps the slot.
			active, _, err := s.Load(ctx, state.ActiveRolloutID)
			if errors.Is(err, jetstream.ErrKeyNotFound) || errors.Is(err, ErrAbandonedRollout) {
				// The slot was claimed but its record was never created (a
				// crash or failure between the two writes). Abandon the ID
				// so a late create of it fails, then release the slot.
				if err := s.abandon(ctx, spec.AuthorityEpoch, state.ActiveRolloutID); err != nil {
					return Record{}, 0, err
				}
				if err := s.releaseSlot(ctx, spec.AuthorityEpoch, state.ActiveRolloutID); err != nil {
					return Record{}, 0, err
				}
				continue
			}
			if err != nil {
				return Record{}, 0, fmt.Errorf("load active rollout %q: %w", state.ActiveRolloutID, err)
			}
			if !active.Phase.Terminal() {
				return Record{}, 0, ErrActiveRollout
			}
			if err := s.syncCell(ctx, withEpoch(active, spec.AuthorityEpoch)); err != nil {
				return Record{}, 0, err
			}
			continue
		}
		if !bound {
			return Record{}, 0, fmt.Errorf("%w: rollout needs a published release stage", ErrNoRelease)
		}
		if bad, err := s.knownBad(ctx, state, spec.ToDigest); err != nil {
			return Record{}, 0, err
		} else if bad {
			return Record{}, 0, ErrKnownBad
		}
		if bad, err := s.knownBad(ctx, state, spec.FromDigest); err != nil {
			return Record{}, 0, err
		} else if bad {
			return Record{}, 0, fmt.Errorf("%w: rollback target digest is known bad", ErrInvalid)
		}
		maxAttempts := spec.Policy.MaxAttempts
		if state.Attempts[spec.ToDigest] >= maxAttempts {
			return Record{}, 0, ErrAttemptsExhausted
		}
		if _, err := New(withKnownBad(spec, state.KnownBad), now); err != nil {
			return Record{}, 0, err
		}
		next := state
		next.ActiveRolloutID = spec.RolloutID
		next.Attempts = make(map[string]int, len(state.Attempts)+1)
		for digest, count := range state.Attempts {
			next.Attempts[digest] = count
		}
		next.Attempts[spec.ToDigest]++
		boundAttempts(next.Attempts, next.KnownBad, spec.ToDigest)
		if err := s.writeCell(ctx, spec.AuthorityEpoch, next, revision); errors.Is(err, ErrConflict) {
			continue
		} else if err != nil {
			return Record{}, 0, err
		}
		return s.createRecord(ctx, spec, next, now)
	}
	return Record{}, 0, ErrConflict
}

store_mutation.text:
func sameRollout(existing Record, spec Spec) error {
	if existing.FromDigest != spec.FromDigest || existing.ToDigest != spec.ToDigest || existing.Kind != spec.Kind {
		return fmt.Errorf("%w: rollout ID is bound to a different rollout", ErrConflict)
	}
	waves, err := PlanWaves(spec.Units, spec.Policy)
	if err != nil {
		return err
	}
	policyDigest, err := spec.Policy.Digest()
	if err != nil {
		return err
	}
	if existing.PolicyDigest != policyDigest || !slices.EqualFunc(existing.Waves, waves, slices.Equal) ||
		!spec.StartedAt.IsZero() && !existing.StartedAt.Equal(spec.StartedAt) {
		return fmt.Errorf("%w: rollout ID is bound to a different plan", ErrConflict)
	}
	return nil
}

func withKnownBad(spec Spec, knownBad []string) Spec {
	spec.KnownBad = append(slices.Clone(spec.KnownBad), knownBad...)
	return spec
}

func (s *Store) createRecord(ctx context.Context, spec Spec, state CellState, now time.Time) (Record, uint64, error) {
	if existing, revision, err := s.Load(ctx, spec.RolloutID); err == nil {
		if err := sameRollout(existing, spec); err != nil {
			return Record{}, 0, err
		}
		return existing, revision, nil
	} else if !errors.Is(err, jetstream.ErrKeyNotFound) {
		return Record{}, 0, err
	}
	record, err := New(withKnownBad(spec, state.KnownBad), now)
	if err != nil {
		return Record{}, 0, err
	}
	encoded, err := protocol.EncodeJSON(record)
	if err != nil {
		return Record{}, 0, err
	}
	if err := s.fencer.Guard(ctx, record.AuthorityEpoch); err != nil {
		return Record{}, 0, err
	}
	revision, err := s.kv.Create(ctx, rolloutKey(record.RolloutID), encoded)
	if errors.Is(err, jetstream.ErrKeyExists) {
		return s.createRecord(ctx, spec, state, now)
	}
	if err != nil {
		return Record{}, 0, err
	}
	recordAdmitted(ctx, record)
	return record, revision, nil
}

// Commit replaces the record stored at revision with next. Identity fields,
// waves and policy are immutable, and the authority epoch may only change
// through Adopt. A terminal record releases the cell slot.
func (s *Store) Commit(ctx context.Context, revision uint64, next Record) (uint64, error) {
	if err := next.Validate(); err != nil {
		return 0, err
	}
	current, storedRevision, err := s.Load(ctx, next.RolloutID)
	if err != nil {
		return 0, err
	}
	if storedRevision != revision {
		return 0, ErrConflict
	}
	if current.AuthorityEpoch != next.AuthorityEpoch {
		return 0, ErrFenced
	}
	if current.Kind != next.Kind || current.Cell != next.Cell || current.FromDigest != next.FromDigest || current.ToDigest != next.ToDigest ||
		current.PolicyDigest != next.PolicyDigest || !slices.EqualFunc(current.Waves, next.Waves, slices.Equal) ||
		!current.StartedAt.Equal(next.StartedAt) {
		return 0, fmt.Errorf("%w: immutable rollout fields changed", ErrInvalid)
	}
	if current.Phase.Terminal() {
		return 0, ErrTerminal
	}
	encoded, err := protocol.EncodeJSON(next)
	if err != nil {
		return 0, err
	}
	if err := s.fencer.Guard(ctx, next.AuthorityEpoch); err != nil {
		return 0, err
	}
	newRevision, err := s.kv.Update(ctx, rolloutKey(next.RolloutID), encoded, revision)
	if errors.Is(err, jetstream.ErrKeyRevisionMismatch) || errors.Is(err, jetstream.ErrKeyExists) {
		return 0, ErrConflict
	}
	if err != nil {
		return 0, err
	}
	recordTransition(ctx, current, next)
	if err := s.syncCell(ctx, next); err != nil {
		return newRevision, fmt.Errorf("record committed; cell slot update pending: %w", err)
	}
	return newRevision, nil
}

// Adopt rebinds an active rollout to a newer authority epoch after a leader
// change. An older epoch can never take a record back.
func (s *Store) Adopt(ctx context.Context, rolloutID string, epoch uint64) (Record, uint64, error) {
	if err := s.fencer.Guard(ctx, epoch); err != nil {
		return Record{}, 0, err
	}
	record, revision, err := s.Load(ctx, rolloutID)
	if err != nil {
		return Record{}, 0, err
	}
	switch {
	case epoch < record.AuthorityEpoch:
		return Record{}, 0, ErrFenced
	case epoch == record.AuthorityEpoch || record.Phase.Terminal():
		return record, revision, nil
	}
	record.AuthorityEpoch = epoch
	encoded, err := protocol.EncodeJSON(record)
	if err != nil {
		return Record{}, 0, err
	}
	newRevision, err := s.kv.Update(ctx, rolloutKey(rolloutID), encoded, revision)
	if errors.Is(err, jetstream.ErrKeyRevisionMismatch) || errors.Is(err, jetstream.ErrKeyExists) {
		return Record{}, 0, ErrConflict
	}
	if err != nil {
		return Record{}, 0, err
	}
	return record, newRevision, nil
}

// syncCell merges the record's known-bad digests into the cell and releases
// the slot once the record is terminal.
func (s *Store) syncCell(ctx context.Context, record Record) error {
	for range cellCASAttempts {
		state, revision, err := s.Cell(ctx)
		if err != nil {
			return err
		}
		next := state
		next.KnownBad = slices.Clone(state.KnownBad)
		for _, digest := range record.KnownBad {
			if !slices.Contains(next.KnownBad, digest) {
				// Durable first: the cell list below is only a bounded
				// cache of the per-digest records.
				if err := s.recordKnownBad(ctx, record.AuthorityEpoch, digest); err != nil {
					return err
				}
				next.KnownBad = append(next.KnownBad, digest)
			}
		}
		// The list keeps insertion order; the oldest entries age out first.
		// Every entry that ages out keeps its durable record, including
		// entries listed before durable records existed.
		if len(next.KnownBad) > MaxKnownBad {
			for _, digest := range next.KnownBad[:len(next.KnownBad)-MaxKnownBad] {
				if err := s.recordKnownBad(ctx, record.AuthorityEpoch, digest); err != nil {
					return err
				}
			}
			next.KnownBad = next.KnownBad[len(next.KnownBad)-MaxKnownBad:]
		}
		next.Attempts = maps.Clone(state.Attempts)
		if record.Phase.Terminal() && state.ActiveRolloutID == record.RolloutID {
			next.ActiveRolloutID = ""
			// The attempt budget limits retries of a rejected digest. A
			// completed rollout proved its digest; an untouched abort never
			// tried it. Refund once as the slot is released so either can retry.
			if (record.Phase == PhaseComplete || record.abortedBeforeUpdate()) && state.Attempts[record.ToDigest] > 0 {
				if next.Attempts[record.ToDigest]--; next.Attempts[record.ToDigest] == 0 {
					delete(next.Attempts, record.ToDigest)
				}
			}
		}
		boundAttempts(next.Attempts, next.KnownBad, "")
		if slices.Equal(next.KnownBad, state.KnownBad) && next.ActiveRolloutID == state.ActiveRolloutID &&
			maps.Equal(next.Attempts, state.Attempts) {
			return nil
		}
		if err := s.writeCell(ctx, record.AuthorityEpoch, next, revision); errors.Is(err, ErrConflict) {
			continue
		} else {
			return err
		}
	}
	return ErrConflict
}

func (s *Store) writeCell(ctx context.Context, epoch uint64, state CellState, revision uint64) error {
	if err := state.validate(s.cell); err != nil {
		return err
	}
	encoded, err := protocol.EncodeJSON(state)
	if err != nil {
		return err
	}
	if err := s.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	if revision == 0 {
		_, err = s.kv.Create(ctx, cellKey, encoded)
	} else {
		_, err = s.kv.Update(ctx, cellKey, encoded, revision)
	}
	if errors.Is(err, jetstream.ErrKeyRevisionMismatch) || errors.Is(err, jetstream.ErrKeyExists) {
		return ErrConflict
	}
	return err
}

// boundAttempts keeps the per-digest attempt map within maxAttemptDigest so
// the cell state never grows into one validate rejects. Counts of digests the
// cell refuses as known bad go first, since the known-bad check already
// refuses them; then the remaining entries in digest order. keep is never
// evicted.
func boundAttempts(attempts map[string]int, knownBad []string, keep string) {
	if len(attempts) <= maxAttemptDigest {
		return
	}
	digests := slices.Sorted(maps.Keys(attempts))
	for _, refused := range []bool{true, false} {
		for _, digest := range digests {
			if len(attempts) <= maxAttemptDigest {
				return
			}
			if digest != keep && slices.Contains(knownBad, digest) == refused {
				delete(attempts, digest)
			}
		}
	}
}

store_recovery.text:
func decodeAbandoned(wire []byte, rolloutID string) (*abandonedMarker, error) {
	var kind struct {
		AbandonedRollout string `json:"abandoned_rollout"`
		SchemaVersion    int    `json:"schema_version"`
	}
	if err := protocol.DecodeTolerant(wire, &kind, maxRecordBytes); err != nil {
		return nil, err
	}
	if kind.AbandonedRollout == "" || kind.SchemaVersion != 0 {
		return nil, nil
	}
	var marker abandonedMarker
	if err := protocol.DecodeStrict(wire, &marker, maxRecordBytes); err != nil {
		return nil, err
	}
	if marker.AbandonedRollout != rolloutID || !entityid.Valid(rolloutID) {
		return nil, fmt.Errorf("%w: abandoned rollout binding", ErrInvalid)
	}
	return &marker, nil
}

// abandon writes the marker for rolloutID unless a record or marker exists.
func (s *Store) abandon(ctx context.Context, epoch uint64, rolloutID string) error {
	encoded, err := protocol.EncodeJSON(abandonedMarker{AbandonedRollout: rolloutID})
	if err != nil {
		return err
	}
	if err := s.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	_, err = s.kv.Create(ctx, rolloutKey(rolloutID), encoded)
	if errors.Is(err, jetstream.ErrKeyExists) {
		// A concurrent create won or the marker is already in place; the
		// next Load tells which.
		if _, _, loadErr := s.Load(ctx, rolloutID); loadErr == nil {
			return ErrActiveRollout
		} else if !errors.Is(loadErr, ErrAbandonedRollout) {
			return loadErr
		}
		return nil
	}
	return err
}

// releaseSlot refunds a proven release reservation once, in the CAS that clears it.
func (s *Store) releaseSlot(ctx context.Context, epoch uint64, rolloutID string) error {
	for range cellCASAttempts {
		state, revision, err := s.Cell(ctx)
		if err != nil {
			return err
		}
		if state.ActiveRolloutID != rolloutID {
			return nil
		}
		if _, _, err := s.Load(ctx, rolloutID); !errors.Is(err, ErrAbandonedRollout) {
			if err != nil {
				return err
			}
			return ErrActiveRollout
		}
		release, _, found, err := s.releaseStage(ctx, rolloutID)
		if err != nil {
			return err
		}
		next := state
		next.ActiveRolloutID = ""
		next.Attempts = maps.Clone(state.Attempts)
		// An arbitrary orphan ID proves no target; never guess from historical counts.
		if found && next.Attempts[release.Digest] > 0 {
			if next.Attempts[release.Digest]--; next.Attempts[release.Digest] == 0 {
				delete(next.Attempts, release.Digest)
			}
		}
		if err := s.writeCell(ctx, epoch, next, revision); errors.Is(err, ErrConflict) {
			continue
		} else {
			return err
		}
	}
	return ErrConflict
}

// withEpoch fences a cell repair with the caller's current epoch instead of
// the finished record's possibly older one.
func withEpoch(record Record, epoch uint64) Record {
	record.AuthorityEpoch = epoch
	return record
}

store_active.text:
func (s *Store) IsKnownBad(ctx context.Context, digest string) (bool, error) {
	if !digestRE.MatchString(digest) {
		return false, fmt.Errorf("%w: known-bad digest", ErrInvalid)
	}
	state, _, err := s.Cell(ctx)
	if err != nil {
		return false, err
	}
	return s.knownBad(ctx, state, digest)
}

// Active returns the record that holds the cell's rollout slot and its KV
// revision. ok is false when the slot is free or names a claim whose record
// was never created; Begin repairs such a slot.
func (s *Store) Active(ctx context.Context) (record Record, revision uint64, ok bool, err error) {
	state, _, err := s.Cell(ctx)
	if err != nil || state.ActiveRolloutID == "" {
		return Record{}, 0, false, err
	}
	record, revision, err = s.Load(ctx, state.ActiveRolloutID)
	if errors.Is(err, ErrAbandonedRollout) {
		return Record{}, 0, false, nil
	}
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return Record{}, 0, false, nil
	}
	if err != nil {
		return Record{}, 0, false, err
	}
	return record, revision, true, nil
}

// RecoverReservation abandons a record-free slot before program planning, including a marker-before-clear crash.
func (s *Store) RecoverReservation(ctx context.Context, epoch uint64) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	state, _, err := s.Cell(ctx)
	if err != nil || state.ActiveRolloutID == "" {
		return err
	}
	if _, _, err := s.Load(ctx, state.ActiveRolloutID); !errors.Is(err, jetstream.ErrKeyNotFound) && !errors.Is(err, ErrAbandonedRollout) {
		return err
	}
	if err := s.abandon(ctx, epoch, state.ActiveRolloutID); err != nil {
		return err
	}
	return s.releaseSlot(ctx, epoch, state.ActiveRolloutID)
}

// Settle releases the cell slot still held by a terminal record whose
// release was interrupted after its commit, fenced by the caller's epoch.
// It is a no-op for an active record.
func (s *Store) Settle(ctx context.Context, record Record, epoch uint64) error {
	if !record.Phase.Terminal() {
		return nil
	}
	if err := s.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	return s.syncCell(ctx, withEpoch(record, epoch))
}

// Matches reports whether record is the rollout spec describes: the same
// digests, kind, waves and policy. A program uses it before it treats an
// earlier record as its completed prerequisite.
func (record Record) Matches(spec Spec) error {
	if record.RolloutID != spec.RolloutID || record.Cell != spec.Cell {
		return fmt.Errorf("%w: rollout ID is bound to a different rollout", ErrConflict)
	}
	return sameRollout(record, spec)
}

release_ids.text:
func generationKey(cell string, generation uint64) string {
	return entityid.Derive("release", cell, strconv.FormatUint(generation, 10))
}

// ReleaseRolloutID is the rollout ID prefix of a desired release generation.
func ReleaseRolloutID(generation uint64) string {
	return entityid.Derive("release-rollout", strconv.FormatUint(generation, 10))
}

// releaseStage resolves derived stage IDs before reading their immutable generation.
func (s *Store) releaseStage(ctx context.Context, id string) (Release, Kind, bool, error) {
	desired, _, err := s.Desired(ctx)
	if err != nil {
		return Release{}, "", false, err
	}
	// Derivation keeps network reads independent of permanent operational history.
	// shortcut: historical IDs cost local hashing; index them if generation counts make that costly.
	for generation := desired.Generation(); generation > 0; generation-- {
		if err := ctx.Err(); err != nil {
			return Release{}, "", false, err
		}
		rolloutID := ReleaseRolloutID(generation)
		for _, stage := range []struct {
			domain string
			kind   Kind
		}{{ControllerReleaseDomain, KindController}, {HostReleaseDomain, KindHost}} {
			if id != entityid.Derive(stage.domain, rolloutID) {
				continue
			}
			release, err := s.generation(ctx, desired, generation)
			if errors.Is(err, ErrNoRelease) {
				return Release{}, "", false, nil
			}
			if err != nil {
				return Release{}, "", false, err
			}
			if release.ID != generationKey(s.cell, generation) {
				return Release{}, "", false, fmt.Errorf("%w: release stage generation ID", ErrInvalid)
			}
			return release, stage.kind, true, nil
		}
	}
	return Release{}, "", false, ctx.Err()
}

release_reads.text:
func (r Release) validate() error {
	if r.ReleaseSequence == 0 && (len(r.SequenceMigration) > 0 || r.SequenceMigrationSHA256 != "") || r.ReleaseSequence > 0 && (len(r.SequenceMigration) == 0 || !digestRE.MatchString(r.SequenceMigrationSHA256) || len(r.Receipt) == 0 || len(r.Delegation) == 0) || len(r.SequenceMigration) > maxReleaseWire {
		return fmt.Errorf("%w: release sequence metadata", ErrInvalid)
	}
	if !entityid.Valid(r.ID) || r.Generation == 0 || !digestRE.MatchString(r.Digest) || r.RunNumber < 0 ||
		r.SourceRevision != "" && !release.ValidSourceRevision(r.SourceRevision) ||
		len(r.Receipt) > maxReleaseWire || len(r.Delegation) > maxReleaseWire ||
		len(r.Delegation) > 0 && len(r.Receipt) == 0 || r.RollbackOf >= r.Generation ||
		(!tokenRE.MatchString(r.Actor) && !entityid.Valid(r.Actor)) || r.CreatedAt.IsZero() {
		return fmt.Errorf("%w: release generation", ErrInvalid)
	}
	return nil
}

// Desired is the cell's newest release generation. Paused stops the executor
// from starting another rollout; a rollout already running still finishes.
type Desired struct {
	OrderingFloor       Release `json:"ordering_floor,omitzero"`
	LegacyFloor         Release `json:"legacy_floor,omitzero"`
	LegacyIssuanceFloor Release `json:"legacy_issuance_floor,omitzero"`
	SchemaVersion       int     `json:"schema_version"`
	Cell                string  `json:"cell"`
	Release             Release `json:"release,omitzero"`
	Paused              bool    `json:"paused,omitzero"`
}

// Generation is the newest generation, zero before the first release.
func (d Desired) Generation() uint64 { return d.Release.Generation }

func (d Desired) validate(cell string) error {
	if (d.SchemaVersion != SchemaVersion && d.SchemaVersion != DesiredSchemaVersion) || d.Cell != cell {
		return fmt.Errorf("%w: desired release", ErrInvalid)
	}
	if d.SchemaVersion == SchemaVersion && (d.OrderingFloor.Generation != 0 || d.LegacyFloor.Generation != 0 || d.LegacyIssuanceFloor.Generation != 0 || d.Release.ReleaseSequence != 0) {
		return fmt.Errorf("%w: legacy desired schema carries sequence state", ErrInvalid)
	}
	if d.OrderingFloor.Generation > 0 {
		if err := d.OrderingFloor.validate(); err != nil {
			return err
		}
		if d.OrderingFloor.ReleaseSequence == 0 {
			return fmt.Errorf("%w: ordering floor", ErrInvalid)
		}
	}
	for _, floor := range []Release{d.LegacyFloor, d.LegacyIssuanceFloor} {
		if floor.Generation > 0 {
			if err := floor.validate(); err != nil {
				return err
			}
			if floor.ReleaseSequence != 0 {
				return fmt.Errorf("%w: legacy ordering floor", ErrInvalid)
			}
		}
	}
	if d.Release.Generation != 0 {
		if d.Release.ReleaseSequence > d.OrderingFloor.ReleaseSequence {
			return fmt.Errorf("%w: desired exceeds retained ordering floor", ErrInvalid)
		}
		return d.Release.validate()
	}
	return nil
}

// Desired returns the record and its revision (zero when absent).
func (s *Store) Desired(ctx context.Context) (Desired, uint64, error) {
	entry, err := s.kv.Get(ctx, desiredKey)
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return Desired{SchemaVersion: DesiredSchemaVersion, Cell: s.cell}, 0, nil
	}
	if err != nil {
		return Desired{}, 0, err
	}
	var desired Desired
	if err := protocol.DecodeTolerant(entry.Value(), &desired, maxRecordBytes); err != nil {
		return Desired{}, 0, err
	}
	if err := desired.validate(s.cell); err != nil {
		return Desired{}, 0, err
	}
	return desired, entry.Revision(), nil
}

// ReleaseGeneration returns one retained generation.
func (s *Store) ReleaseGeneration(ctx context.Context, generation uint64) (Release, error) {
	desired, _, err := s.Desired(ctx)
	if err != nil {
		return Release{}, err
	}
	return s.generation(ctx, desired, generation)
}

// generation reads a retained copy. The copy has no schema version of its
// own: the desired record's, which every caller has validated, covers it. A
// breaking Release change raises DesiredSchemaVersion, so an older controller
// refuses the desired record and never reads a newer generation it would
// misread; a newer binary's added members are skipped, as in the desired
// record itself.
func (s *Store) generation(ctx context.Context, desired Desired, generation uint64) (Release, error) {
	if generation != 0 && generation == desired.Generation() {
		return desired.Release, nil
	}
	if generation == 0 || generation > desired.Generation() {
		return Release{}, fmt.Errorf("%w: %d", ErrNoRelease, generation)
	}
	entry, err := s.kv.Get(ctx, generationKey(s.cell, generation))
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return Release{}, fmt.Errorf("%w: %d is no longer retained", ErrNoRelease, generation)
	}
	if err != nil {
		return Release{}, err
	}
	var release Release
	if err := protocol.DecodeTolerant(entry.Value(), &release, maxRecordBytes); err != nil {
		return Release{}, err
	}
	if err := release.validate(); err != nil || release.Generation != generation || release.ID != generationKey(s.cell, generation) {
		return Release{}, fmt.Errorf("%w: stored generation %d", ErrInvalid, generation)
	}
	return release, nil
}

release_writes.text:
func (s *Store) PublishRelease(ctx context.Context, epoch uint64, release Release) (Release, error) {
	if release.ReleaseSequence > 0 || len(release.SequenceMigration) > 0 || release.SequenceMigrationSHA256 != "" || release.RollbackOf != 0 {
		return Release{}, fmt.Errorf("%w: sequenced releases require signature admission; rollbacks require retained generation", ErrInvalid)
	}
	if err := rejectSequencedReceipt(release.Receipt); err != nil {
		return Release{}, err
	}
	return s.publishRelease(ctx, epoch, release, false)
}

func (s *Store) publishRelease(ctx context.Context, epoch uint64, release Release, rollback bool) (Release, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if bad, err := s.IsKnownBad(ctx, release.Digest); err != nil {
		return Release{}, err
	} else if bad {
		return Release{}, ErrKnownBad
	}
	for range cellCASAttempts {
		desired, revision, err := s.Desired(ctx)
		if err != nil {
			return Release{}, err
		}
		seeded, err := s.seedReleaseOrdering(ctx, desired)
		if err != nil {
			return Release{}, err
		}
		next := seeded
		normalized := release
		normalized.Generation = desired.Generation() + 1
		normalized.ID = generationKey(s.cell, normalized.Generation)
		normalized.CreatedAt = release.CreatedAt.UTC()
		if err := normalized.validate(); err != nil {
			return Release{}, err
		}
		if !rollback {
			if err := advanceReleaseOrdering(&next, normalized, s.cell); err != nil {
				return Release{}, err
			}
		}
		if desired.Generation() > 0 && desired.Release.Digest == release.Digest {
			retry, err := s.retryUntouchedRelease(ctx, desired.Release, release)
			if err != nil {
				return Release{}, err
			}
			if !retry {
				if desired.SchemaVersion != DesiredSchemaVersion || desired.OrderingFloor.ReleaseSequence != next.OrderingFloor.ReleaseSequence || desired.LegacyFloor.Generation != next.LegacyFloor.Generation || desired.LegacyIssuanceFloor.Generation != next.LegacyIssuanceFloor.Generation {
					if err := s.writeDesired(ctx, epoch, next, revision); errors.Is(err, ErrConflict) {
						continue
					} else if err != nil {
						return Release{}, err
					}
				}
				return desired.Release, ErrReleaseUnchanged
			}
		}
		next.Release = normalized
		next.SchemaVersion = DesiredSchemaVersion
		if err := next.validate(s.cell); err != nil {
			return Release{}, err
		}
		// The generation being replaced is retained before the record
		// moves; a copy lost to a crash is written again by the next
		// publish, since the record still holds it.
		if desired.Generation() > 0 {
			if err := s.retain(ctx, epoch, desired.Release); err != nil {
				return Release{}, err
			}
		}
		if err := s.writeDesired(ctx, epoch, next, revision); errors.Is(err, ErrConflict) {
			continue
		} else if err != nil {
			return Release{}, err
		}
		if newest := next.Generation(); newest > ReleaseHistory {
			// Best effort: a missed purge only keeps one more old copy.
			oldest := newest - ReleaseHistory
			state, _, err := s.Cell(ctx)
			if err == nil && state.ActiveRolloutID != entityid.Derive(ControllerReleaseDomain, ReleaseRolloutID(oldest)) &&
				state.ActiveRolloutID != entityid.Derive(HostReleaseDomain, ReleaseRolloutID(oldest)) && s.fencer.Guard(ctx, epoch) == nil {
				_ = s.kv.Purge(ctx, generationKey(s.cell, oldest))
			}
		}
		return next.Release, nil
	}
	return Release{}, ErrConflict
}

func (s *Store) retryUntouchedRelease(ctx context.Context, previous, next Release) (bool, error) {
	if previous.RollbackOf != 0 || next.RollbackOf != 0 || !newerReleaseOrder(previous, next) || next.ReleaseSequence == 0 && !next.CreatedAt.After(previous.CreatedAt) {
		return false, nil
	}
	aborted := false
	for _, domain := range []string{ControllerReleaseDomain, HostReleaseDomain} {
		record, _, err := s.Load(ctx, entityid.Derive(domain, ReleaseRolloutID(previous.Generation)))
		if errors.Is(err, jetstream.ErrKeyNotFound) {
			continue
		}
		if errors.Is(err, ErrAbandonedRollout) {
			aborted = true
			continue
		}
		if err != nil || !record.abortedBeforeUpdate() {
			return false, err
		}
		kind := KindController
		if domain == HostReleaseDomain {
			kind = KindHost
		}
		if record.ToDigest != previous.Digest || record.Kind != kind || !record.StartedAt.Equal(previous.CreatedAt) {
			return false, fmt.Errorf("%w: aborted release stage binding", ErrInvalid)
		}
		aborted = true
	}
	return aborted, nil
}

func (s *Store) retain(ctx context.Context, epoch uint64, release Release) error {
	encoded, err := protocol.EncodeJSON(release)
	if err != nil {
		return err
	}
	if err := s.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	if _, err := s.kv.Put(ctx, generationKey(s.cell, release.Generation), encoded); err != nil {
		return fmt.Errorf("retain release generation: %w", err)
	}
	return nil
}

// RollbackRelease publishes a new generation that repeats generation to.
// History is never rewritten: a rollback is itself a generation, so a later
// one can roll it back again.
func (s *Store) RollbackRelease(ctx context.Context, epoch, to uint64, actor string, now time.Time) (Release, error) {
	desired, _, err := s.Desired(ctx)
	if err != nil {
		return Release{}, err
	}
	if to == 0 || to >= desired.Generation() {
		return Release{}, fmt.Errorf("%w: roll back to a generation before %d", ErrInvalid, desired.Generation())
	}
	target, err := s.generation(ctx, desired, to)
	if err != nil {
		return Release{}, err
	}
	repeat := target
	repeat.RollbackOf, repeat.Actor, repeat.CreatedAt = to, actor, now
	return s.publishRelease(ctx, epoch, repeat, true)
}

// PauseReleases sets the cell's pause, fenced by epoch.
func (s *Store) PauseReleases(ctx context.Context, epoch uint64, paused bool) (Desired, error) {
	for range cellCASAttempts {
		desired, revision, err := s.Desired(ctx)
		if err != nil {
			return Desired{}, err
		}
		if desired.Paused == paused {
			return desired, nil
		}
		desired.Paused = paused
		if err := s.writeDesired(ctx, epoch, desired, revision); errors.Is(err, ErrConflict) {
			continue
		} else if err != nil {
			return Desired{}, err
		}
		return desired, nil
	}
	return Desired{}, ErrConflict
}

func (s *Store) writeDesired(ctx context.Context, epoch uint64, desired Desired, revision uint64) error {
	desired.SchemaVersion = DesiredSchemaVersion
	if err := desired.validate(s.cell); err != nil {
		return err
	}
	encoded, err := protocol.EncodeJSON(desired)
	if err != nil {
		return err
	}
	if err := s.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	if revision == 0 {
		_, err = s.kv.Create(ctx, desiredKey, encoded)
	} else {
		_, err = s.kv.Update(ctx, desiredKey, encoded, revision)
	}
	if errors.Is(err, jetstream.ErrKeyRevisionMismatch) || errors.Is(err, jetstream.ErrKeyExists) {
		return ErrConflict
	}
	return err
}

release_inventory.text:
func (s *Store) retainedReleases(ctx context.Context, desired Desired) ([]Release, error) {
	var releases []Release
	if desired.Generation() > 0 {
		releases = append(releases, desired.Release)
	}
	// Failed best-effort purges leave readable rollback targets beyond ReleaseHistory.
	keys, err := releasechannel.PinKeys(ctx, s.kv, ">")
	if err != nil {
		return nil, err
	}
	for _, key := range keys {
		if key == cellKey || key == desiredKey || strings.HasPrefix(key, "knownbad.") {
			continue
		}
		if !entityid.Valid(key) {
			return nil, fmt.Errorf("%w: retained record key %q", ErrInvalid, key)
		}
		entry, err := s.kv.Get(ctx, key)
		if err != nil {
			return nil, err
		}
		// Operational records share the entity-key namespace with retained releases.
		var kind struct {
			HostMembership
			SchemaVersion int          `json:"schema_version"`
			ID            string       `json:"id"`
			Generation    uint64       `json:"generation"`
			RolloutID     string       `json:"rollout_id"`
			Scope         *trust.Scope `json:"scope"`
			Unit          string       `json:"unit"`
			OperationID   string       `json:"operation_id"`
		}
		if err := protocol.DecodeTolerant(entry.Value(), &kind, maxRecordBytes); err != nil {
			return nil, err
		}
		step := kind.Scope != nil && kind.Scope.Slot != "" && key == entityid.Derive("rollout-step", kind.Scope.Slot)
		reply := kind.Unit != "" && entityid.Valid(kind.OperationID) && key == entityid.Derive("rollout-step-reply", kind.Unit)
		marker, err := decodeAbandoned(entry.Value(), key)
		if err != nil {
			return nil, err
		}
		abandoned := marker != nil
		joined := kind.Node != "" && kind.PublicKey != "" && key == HostMembershipKey(kind.Node)
		if kind.ID == "" && kind.Generation == 0 && (kind.RolloutID == key || step || reply || abandoned || joined) {
			continue
		}
		var release Release
		if err := protocol.DecodeTolerant(entry.Value(), &release, maxRecordBytes); err != nil {
			return nil, err
		}
		if err := release.validate(); err != nil || generationKey(s.cell, release.Generation) != key || release.ID != key {
			return nil, fmt.Errorf("%w: stored generation key %q", ErrInvalid, key)
		}
		releases = append(releases, release)
	}
	return releases, nil
}

release_ordering_guard.text:
func rejectSequencedReceipt(wire []byte) error {
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil || envelope.Scope.Domain != release.UpdateReceiptDomain {
		return nil
	}
	var receipt release.BinaryUpdateReceipt
	if err := protocol.DecodeStrict(envelope.Payload, &receipt, trust.MaxPayloadBytes); err != nil {
		return err
	}
	if receipt.ReleaseSequence > 0 || receipt.SequenceMigrationSHA256 != "" {
		return fmt.Errorf("%w: signed sequence requires signature admission", ErrInvalid)
	}
	return nil
}

release_ordering.text:
func (s *Store) seedReleaseOrdering(ctx context.Context, desired Desired) (Desired, error) {
	if desired.OrderingFloor.Generation > 0 || desired.LegacyFloor.Generation > 0 && desired.LegacyIssuanceFloor.Generation > 0 || desired.Generation() == 0 {
		return desired, nil
	}
	retained, err := s.retainedReleases(ctx, desired)
	if err != nil {
		return Desired{}, err
	}
	for _, historical := range retained {
		if historical.ReleaseSequence > 0 {
			return Desired{}, fmt.Errorf("%w: sequenced history has no durable floor", ErrInvalid)
		}
		if desired.LegacyFloor.Generation == 0 || historical.RunNumber > desired.LegacyFloor.RunNumber {
			desired.LegacyFloor = historical
		}
		if desired.LegacyIssuanceFloor.Generation == 0 || historical.CreatedAt.After(desired.LegacyIssuanceFloor.CreatedAt) {
			desired.LegacyIssuanceFloor = historical
		}
	}
	return desired, nil
}

func advanceReleaseOrdering(desired *Desired, next Release, cell string) error {
	floor := desired.OrderingFloor
	if floor.ReleaseSequence > 0 {
		if next.SequenceMigrationSHA256 != floor.SequenceMigrationSHA256 {
			return fmt.Errorf("%w: release ordering migration cannot change", ErrInvalid)
		}
		if next.ReleaseSequence < floor.ReleaseSequence {
			return fmt.Errorf("%w: signer sequence %d is below retained floor %d", ErrInvalid, next.ReleaseSequence, floor.ReleaseSequence)
		}
		if next.ReleaseSequence == floor.ReleaseSequence {
			same, err := sameSequencedContent(floor, next)
			if err != nil {
				return err
			}
			if !same {
				return fmt.Errorf("%w: signer sequence already names another release", ErrInvalid)
			}
			if desired.Release.Digest != next.Digest || desired.Release.RollbackOf != 0 {
				return fmt.Errorf("%w: retained sequence cannot restart a rolled-back release", ErrInvalid)
			}
			return nil
		}
	}
	if next.ReleaseSequence > 0 {
		envelope, err := trust.DecodeEnvelope(next.SequenceMigration)
		if err != nil {
			return err
		}
		var migration release.SequenceMigration
		if err := protocol.DecodeStrict(envelope.Payload, &migration, trust.MaxPayloadBytes); err != nil {
			return err
		}
		if !migration.AdmitsLegacyFloor(strings.ToUpper(cell), desired.LegacyFloor.RunNumber, desired.LegacyIssuanceFloor.CreatedAt) {
			return fmt.Errorf("%w: migration omits retained legacy run floor %d", ErrInvalid, desired.LegacyFloor.RunNumber)
		}
		desired.OrderingFloor = next
	} else {
		if next.RunNumber < desired.LegacyFloor.RunNumber {
			return fmt.Errorf("%w: CI run is below retained legacy floor", ErrInvalid)
		}
		if next.CreatedAt.Before(desired.LegacyIssuanceFloor.CreatedAt) {
			return fmt.Errorf("%w: issuance is below retained legacy floor", ErrInvalid)
		}
		if next.RunNumber > 0 && next.RunNumber == desired.LegacyFloor.RunNumber && (next.Digest != desired.LegacyFloor.Digest || next.SourceRevision != desired.LegacyFloor.SourceRevision) {
			return fmt.Errorf("%w: CI run already names another release", ErrInvalid)
		}
		if desired.LegacyFloor.Generation == 0 || next.RunNumber > desired.LegacyFloor.RunNumber {
			desired.LegacyFloor = next
		}
		if desired.LegacyIssuanceFloor.Generation == 0 || next.CreatedAt.After(desired.LegacyIssuanceFloor.CreatedAt) {
			desired.LegacyIssuanceFloor = next
		}
	}
	return nil
}

func newerReleaseOrder(previous, next Release) bool {
	if previous.ReleaseSequence > 0 || next.ReleaseSequence > 0 {
		return next.ReleaseSequence > previous.ReleaseSequence
	}
	return next.RunNumber > previous.RunNumber
}

pin_keys.text:
func PinKeys(ctx context.Context, kv jetstream.KeyValue, filter string) ([]string, error) {
	watcher, err := kv.WatchFiltered(ctx, []string{filter}, jetstream.MetaOnly(), jetstream.IgnoreDeletes())
	if err != nil {
		return nil, err
	}
	defer watcher.Stop()
	var keys []string
	for {
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case entry, open := <-watcher.Updates():
			if !open {
				return nil, errors.New("release pin watcher closed before inventory completed")
			}
			if entry == nil {
				if err := ctx.Err(); err != nil {
					return nil, err
				}
				return keys, nil
			}
			keys = append(keys, entry.Key())
		}
	}
}

waves.text:
func PlanWaves(units []Unit, policy Policy) ([][]string, error) {
	if err := policy.Validate(); err != nil {
		return nil, err
	}
	if len(units) == 0 || len(units) > MaxUnits {
		return nil, fmt.Errorf("%w: unit count", ErrInvalid)
	}
	ordered := slices.Clone(units)
	slices.SortFunc(ordered, func(a, b Unit) int { return cmp.Compare(a.ID, b.ID) })
	var seeds, rest []Unit
	seen := make(map[string]struct{}, len(ordered))
	for _, unit := range ordered {
		if !tokenRE.MatchString(unit.ID) || !tokenRE.MatchString(unit.Group) {
			return nil, fmt.Errorf("%w: unit identity %q", ErrInvalid, unit.ID)
		}
		if _, duplicate := seen[unit.ID]; duplicate {
			return nil, fmt.Errorf("%w: duplicate unit %q", ErrInvalid, unit.ID)
		}
		seen[unit.ID] = struct{}{}
		if unit.Seed {
			seeds = append(seeds, unit)
		} else {
			rest = append(rest, unit)
		}
	}
	if len(seeds) > 1 {
		return nil, fmt.Errorf("%w: more than one seed unit", ErrInvalid)
	}
	var waves [][]string
	first := true
	for len(rest) > 0 {
		limit := policy.BatchSize
		if first {
			limit = policy.CanaryUnits
		}
		wave, remaining := takeWave(rest, limit)
		waves = append(waves, wave)
		rest = remaining
		first = false
	}
	for _, seed := range seeds {
		waves = append(waves, []string{seed.ID})
	}
	return waves, nil
}

// takeWave greedily selects up to limit units with pairwise distinct groups,
// preserving order for the units it leaves behind.
func takeWave(units []Unit, limit int) ([]string, []Unit) {
	groups := map[string]struct{}{}
	var wave []string
	var remaining []Unit
	for _, unit := range units {
		if _, taken := groups[unit.Group]; len(wave) < limit && !taken {
			groups[unit.Group] = struct{}{}
			wave = append(wave, unit.ID)
			continue
		}
		remaining = append(remaining, unit)
	}
	return wave, remaining
}

core_new.text:
func New(spec Spec, now time.Time) (Record, error) {
	if now.IsZero() || spec.StartedAt.After(now) {
		return Record{}, fmt.Errorf("%w: start time", ErrInvalid)
	}
	if slices.Contains(spec.KnownBad, spec.ToDigest) {
		return Record{}, ErrKnownBad
	}
	waves, err := PlanWaves(spec.Units, spec.Policy)
	if err != nil {
		return Record{}, err
	}
	policyDigest, err := spec.Policy.Digest()
	if err != nil {
		return Record{}, err
	}
	units := make(map[string]UnitProgress, len(spec.Units))
	for _, unit := range spec.Units {
		units[unit.ID] = UnitProgress{State: UnitPending, Group: unit.Group, Seed: unit.Seed}
	}
	for wave, ids := range waves {
		for _, id := range ids {
			progress := units[id]
			progress.Wave = wave
			units[id] = progress
		}
	}
	knownBad := slices.Clone(spec.KnownBad)
	slices.Sort(knownBad)
	started := spec.StartedAt
	if started.IsZero() {
		started = now
	}
	record := Record{
		SchemaVersion: SchemaVersion, RolloutID: spec.RolloutID, Kind: spec.Kind, Cell: spec.Cell,
		FromDigest: spec.FromDigest, ToDigest: spec.ToDigest, Policy: spec.Policy, PolicyDigest: policyDigest,
		Phase: PhasePending, Waves: waves, Units: units, KnownBad: slices.Compact(knownBad),
		StartedAt: started.UTC(), PhaseStartedAt: now.UTC(), AuthorityEpoch: spec.AuthorityEpoch,
	}
	if err := record.Validate(); err != nil {
		return Record{}, err
	}
	return record, nil
}

core_apply.text:
func Apply(record Record, event Event) (Record, error) {
	if err := record.Validate(); err != nil {
		return Record{}, err
	}
	if event.At.IsZero() || len(event.Reason) > maxReason {
		return Record{}, fmt.Errorf("%w: event time or reason", ErrInvalid)
	}
	if record.Phase.Terminal() {
		return Record{}, ErrTerminal
	}
	next := record.Clone()
	at := event.At.UTC()
	if completionEvent(event.Kind) || event.Kind == EventStart {
		// A completion that arrives after its phase deadline must not erase
		// that deadline: enforce it first, exactly as a tick at the same
		// instant would, and drop the late completion if it fired.
		phase, wave := next.Phase, next.WaveIndex
		next.tick(at)
		if next.Phase != phase || next.WaveIndex != wave {
			if err := next.Validate(); err != nil {
				return Record{}, err
			}
			return next, nil
		}
	}
	var err error
	switch event.Kind {
	case EventStart:
		err = next.start(at)
	case EventPreflightPassed:
		err = next.preflightPassed(at)
	case EventPreflightFailed:
		err = next.requirePhase(PhasePreflight)
		if err == nil {
			next.finish(PhaseAborted, at, reasonOr(event.Reason, "preflight failed"))
		}
	case EventPrepared:
		err = next.prepared(event.Unit, at)
	case EventHealthy:
		err = next.healthy(event.Unit, event.Health, at)
	case EventUnhealthy, EventHeld:
		// A held forward step rolls back like an unhealthy one; rollback
		// itself, not the forward unit, is what freezes for a human.
		err = next.failed(event.Unit, at, reasonOr(event.Reason, string(event.Kind)))
	case EventRollbackServing:
		err = next.rollbackServing(event.Unit, at)
	case EventRollbackHeld:
		err = next.rollbackHeld(event.Unit, at, reasonOr(event.Reason, "rollback held"))
	case EventTick:
		next.tick(at)
	case EventAbort:
		err = next.abort(at, reasonOr(event.Reason, "operator abort"))
	case EventFreeze:
		if next.Phase == PhaseFrozen {
			return Record{}, ErrInvalidTransition
		}
		next.enter(PhaseFrozen, at, time.Time{}, reasonOr(event.Reason, "frozen"))
	case EventResume:
		err = next.resume(at, event.Left)
	default:
		err = fmt.Errorf("%w: event kind", ErrInvalid)
	}
	if err != nil {
		return Record{}, err
	}
	if err := next.Validate(); err != nil {
		return Record{}, err
	}
	return next, nil
}

// completionEvent reports events that complete a phase with a deadline.
func completionEvent(kind EventKind) bool {
	return kind == EventPreflightPassed || kind == EventPrepared || kind == EventHealthy
}

// boundReason keeps a stored reason within maxReason bytes without splitting
// a UTF-8 rune, so a prefixed failure reason can never fail validation and
// discard the rollback it describes.
func boundReason(reason string) string {
	if len(reason) <= maxReason {
		return reason
	}
	const ellipsis = "..."
	cut := maxReason - len(ellipsis)
	for cut > 0 && !utf8.RuneStart(reason[cut]) {
		cut--
	}
	return reason[:cut] + ellipsis
}

func reasonOr(reason, fallback string) string {
	if reason == "" {
		return fallback
	}
	return reason
}

func (record *Record) requirePhase(phases ...Phase) error {
	if !slices.Contains(phases, record.Phase) {
		return fmt.Errorf("%w: %s", ErrInvalidTransition, record.Phase)
	}
	return nil
}

func (record *Record) enter(phase Phase, at, deadline time.Time, reason string) {
	if (phase == PhasePreflight || phase.preparing() || phase.soaking()) && deadline.After(record.StartedAt.Add(ObservationBudget)) {
		deadline = record.StartedAt.Add(ObservationBudget)
	}
	record.Phase = phase
	record.PhaseStartedAt = at
	record.PhaseDeadline = deadline
	record.Reason = boundReason(reason)
}

func (record *Record) finish(phase Phase, at time.Time, reason string) {
	record.enter(phase, at, time.Time{}, reason)
}

func (record *Record) start(at time.Time) error {
	if err := record.requirePhase(PhasePending); err != nil {
		return err
	}
	if slices.Contains(record.KnownBad, record.ToDigest) {
		record.finish(PhaseAborted, at, "target digest is known bad")
		return nil
	}
	record.enter(PhasePreflight, at, at.Add(seconds(record.Policy.PreflightSeconds)), "")
	return nil
}

func (record *Record) preflightPassed(at time.Time) error {
	if err := record.requirePhase(PhasePreflight); err != nil {
		return err
	}
	if slices.Contains(record.KnownBad, record.ToDigest) {
		record.finish(PhaseAborted, at, "target digest is known bad")
		return nil
	}
	record.beginWave(0, at)
	return nil
}

// beginWave marks the wave's units as preparing. The executor must only
// issue each prepare after the unit's group peers are serving (see Action).
func (record *Record) beginWave(wave int, at time.Time) {
	record.WaveIndex = wave
	phase := PhaseBatch
	if wave == 0 {
		phase = PhaseCanary
	}
	for _, id := range record.Waves[wave] {
		progress := record.Units[id]
		progress.State = UnitPreparing
		progress.HealthyReports, progress.FirstHealthyAt, progress.ProcessID, progress.StartNonce = 0, time.Time{}, 0, ""
		progress.LastHealthyAt = time.Time{}
		record.Units[id] = progress
	}
	record.enter(phase, at, at.Add(seconds(record.Policy.ProofDeadlineSeconds)), "")
}

func (record *Record) currentWaveUnit(unit string) (UnitProgress, error) {
	progress, exists := record.Units[unit]
	if !exists || progress.Wave != record.WaveIndex {
		return UnitProgress{}, fmt.Errorf("%w: unit %q is not in the current wave", ErrInvalidTransition, unit)
	}
	return progress, nil
}

func (record *Record) prepared(unit string, at time.Time) error {
	if !record.Phase.preparing() && !record.Phase.soaking() {
		return fmt.Errorf("%w: %s", ErrInvalidTransition, record.Phase)
	}
	progress, err := record.currentWaveUnit(unit)
	if err != nil {
		return err
	}
	switch progress.State {
	case UnitSoaking:
		return nil
	case UnitPreparing:
	default:
		return fmt.Errorf("%w: unit %q is %s", ErrInvalidTransition, unit, progress.State)
	}
	progress.State = UnitSoaking
	record.Units[unit] = progress
	if record.Phase.preparing() && record.waveState(UnitSoaking) {
		phase := PhaseBatchSoak
		if record.Phase == PhaseCanary {
			phase = PhaseCanarySoak
		}
		record.enter(phase, at, at.Add(seconds(record.Policy.ProofDeadlineSeconds)), "")
	}
	return nil
}

func (record *Record) waveState(state UnitState) bool {
	for _, id := range record.Waves[record.WaveIndex] {
		if record.Units[id].State != state {
			return false
		}
	}
	return true
}

func (record *Record) healthy(unit string, health Health, at time.Time) error {
	if !record.Phase.preparing() && !record.Phase.soaking() {
		return fmt.Errorf("%w: %s", ErrInvalidTransition, record.Phase)
	}
	progress, err := record.currentWaveUnit(unit)
	if err != nil {
		return err
	}
	if progress.State != UnitSoaking {
		return fmt.Errorf("%w: unit %q is %s", ErrInvalidTransition, unit, progress.State)
	}
	if health.ProcessID <= 0 || !nonceRE.MatchString(health.StartNonce) || health.ObservedAt.IsZero() {
		return fmt.Errorf("%w: health report identity", ErrInvalid)
	}
	if health.ObservedAt.Before(record.PhaseStartedAt) || health.ObservedAt.After(at.Add(time.Minute)) {
		// A report older than the current phase cannot prove the new
		// process, in the preparing phase as little as in the soak: a
		// replayed report would start the soak clock in the past.
		return fmt.Errorf("%w: stale or future health report", ErrInvalid)
	}
	if health.Digest != record.ToDigest {
		record.startRollback(at, fmt.Sprintf("unit %s serves an unexpected digest", unit))
		return nil
	}
	if progress.HealthyReports > 0 && (progress.ProcessID != health.ProcessID || progress.StartNonce != health.StartNonce) {
		record.startRollback(at, fmt.Sprintf("unit %s restarted during soak", unit))
		return nil
	}
	observed := health.ObservedAt.UTC()
	if progress.HealthyReports > 0 && !observed.After(progress.LastHealthyAt) {
		// A replayed or reordered report proves nothing new.
		return nil
	}
	if progress.HealthyReports == 0 {
		progress.FirstHealthyAt = observed
		progress.ProcessID, progress.StartNonce = health.ProcessID, health.StartNonce
	}
	progress.LastHealthyAt = observed
	progress.HealthyReports++
	record.Units[unit] = progress
	record.advanceIfSoaked(at)
	return nil
}

func (record *Record) failed(unit string, at time.Time, reason string) error {
	if !record.Phase.preparing() && !record.Phase.soaking() {
		return fmt.Errorf("%w: %s", ErrInvalidTransition, record.Phase)
	}
	progress, exists := record.Units[unit]
	if !exists || !progress.State.touched() {
		return fmt.Errorf("%w: unit %q has not moved", ErrInvalidTransition, unit)
	}
	record.startRollback(at, fmt.Sprintf("unit %s: %s", unit, reason))
	return nil
}

func (record *Record) soakDuration() time.Duration {
	if record.Phase == PhaseCanarySoak {
		return seconds(record.Policy.CanarySoakSeconds)
	}
	return seconds(record.Policy.BatchSoakSeconds)
}

// advanceIfSoaked promotes the wave once every unit has produced the
// required consecutive reports from one incarnation over the soak window.
func (record *Record) advanceIfSoaked(at time.Time) {
	if !record.Phase.soaking() {
		return
	}
	for _, id := range record.Waves[record.WaveIndex] {
		progress := record.Units[id]
		// The observations, not elapsed tick time, must span the window: a
		// unit that stopped reporting early never completes its soak.
		if progress.State != UnitSoaking || progress.HealthyReports < record.Policy.MinHealthyReports ||
			progress.LastHealthyAt.Before(progress.FirstHealthyAt.Add(record.soakDuration())) {
			return
		}
	}
	for _, id := range record.Waves[record.WaveIndex] {
		progress := record.Units[id]
		progress.State = UnitPromoted
		record.Units[id] = progress
	}
	if record.WaveIndex+1 < len(record.Waves) {
		record.beginWave(record.WaveIndex+1, at)
		return
	}
	record.finish(PhaseComplete, at, "")
}

core_deadlines.text:
func (record *Record) tick(at time.Time) {
	if (record.Phase == PhasePending || record.Phase == PhasePreflight || record.Phase.preparing() || record.Phase.soaking()) &&
		!at.Before(record.StartedAt.Add(ObservationBudget)) {
		reason := "release exceeded its fixed 20-minute observation budget"
		if record.Phase == PhasePending || record.Phase == PhasePreflight {
			record.finish(PhaseAborted, at, reason)
		} else {
			record.startRollback(at, reason)
		}
		return
	}
	switch {
	case record.Phase == PhasePreflight && !at.Before(record.PhaseDeadline):
		record.finish(PhaseAborted, at, "preflight deadline exceeded")
	case record.Phase.preparing() && !at.Before(record.PhaseDeadline):
		record.startRollback(at, "prepare deadline exceeded")
	case record.Phase.soaking():
		if !at.Before(record.PhaseDeadline) {
			for _, id := range record.Waves[record.WaveIndex] {
				if record.Units[id].HealthyReports == 0 {
					record.startRollback(at, fmt.Sprintf("unit %s missed its serving-proof deadline", id))
					return
				}
			}
		}
		wave := record.WaveIndex
		record.advanceIfSoaked(at)
		// Every unit that proved itself before the serving-proof deadline
		// has finished its soak window by deadline+soak, and has reported
		// again within minSoakGap after it. A wave still soaking then has a
		// unit that stopped reporting (for example a hung process after one
		// healthy report); it must not hold the cell's rollout slot forever.
		if record.Phase.soaking() && record.WaveIndex == wave &&
			!at.Before(record.PhaseDeadline.Add(record.soakDuration()).Add(minSoakGap)) {
			record.startRollback(at, "soak did not complete before its deadline")
		}
	case record.Phase == PhaseRollingBack && !at.Before(record.PhaseDeadline):
		head := record.rollbackHead()
		if head != "" {
			progress := record.Units[head]
			progress.State = UnitHeld
			record.Units[head] = progress
		}
		record.enter(PhaseFrozen, at, time.Time{}, "rollback deadline exceeded")
	}
}

// startRollback durably marks ToDigest known bad in the same record write
// that first orders any rollback action, then rolls back every touched unit
// newest first.
func (record *Record) startRollback(at time.Time, reason string) {
	if !slices.Contains(record.KnownBad, record.ToDigest) {
		record.KnownBad = append(record.KnownBad, record.ToDigest)
		slices.Sort(record.KnownBad)
		if len(record.KnownBad) > MaxKnownBad {
			// Keep the current target; the cell list retains the dropped entry.
			drop := 0
			if record.KnownBad[0] == record.ToDigest {
				drop = 1
			}
			record.KnownBad = slices.Delete(record.KnownBad, drop, drop+1)
		}
	}
	var touched []string
	for id, progress := range record.Units {
		if progress.State.touched() {
			touched = append(touched, id)
		}
	}
	slices.SortFunc(touched, func(a, b string) int {
		if order := cmp.Compare(record.Units[b].Wave, record.Units[a].Wave); order != 0 {
			return order
		}
		return cmp.Compare(b, a)
	})
	for _, id := range touched {
		progress := record.Units[id]
		progress.State = UnitRollingBack
		record.Units[id] = progress
	}
	record.RollbackOrder = touched
	if len(touched) == 0 {
		record.finish(PhaseRolledBack, at, reason)
		return
	}
	record.enter(PhaseRollingBack, at, at.Add(seconds(record.Policy.RollbackDeadlineSeconds)), reason)
}

// rollbackHead returns the next unit to return to FromDigest. Rollback moves
// one unit at a time so the group peer of each step keeps serving.
func (record *Record) rollbackHead() string {
	for _, id := range record.RollbackOrder {
		if record.Units[id].State == UnitRollingBack {
			return id
		}
	}
	return ""
}

func (record *Record) rollbackServing(unit string, at time.Time) error {
	if err := record.requirePhase(PhaseRollingBack); err != nil {
		return err
	}
	if head := record.rollbackHead(); head != unit {
		if progress, exists := record.Units[unit]; exists && progress.State == UnitRolledBack {
			return nil
		}
		return fmt.Errorf("%w: unit %q is not the rollback head", ErrInvalidTransition, unit)
	}
	progress := record.Units[unit]
	progress.State = UnitRolledBack
	record.Units[unit] = progress
	if record.rollbackHead() == "" {
		record.finish(PhaseRolledBack, at, record.Reason)
		return nil
	}
	record.enter(PhaseRollingBack, at, at.Add(seconds(record.Policy.RollbackDeadlineSeconds)), record.Reason)
	return nil
}

func (record *Record) rollbackHeld(unit string, at time.Time, reason string) error {
	if err := record.requirePhase(PhaseRollingBack); err != nil {
		return err
	}
	if head := record.rollbackHead(); head != unit {
		return fmt.Errorf("%w: unit %q is not the rollback head", ErrInvalidTransition, unit)
	}
	progress := record.Units[unit]
	progress.State = UnitHeld
	record.Units[unit] = progress
	// Never retarget ToDigest: a held rollback stops for a human.
	record.enter(PhaseFrozen, at, time.Time{}, reason)
	return nil
}

func (record *Record) abort(at time.Time, reason string) error {
	switch {
	case record.Phase == PhasePending || record.Phase == PhasePreflight:
		record.finish(PhaseAborted, at, reason)
	case record.Phase.preparing() || record.Phase.soaking():
		record.startRollback(at, reason)
	default:
		return fmt.Errorf("%w: %s", ErrInvalidTransition, record.Phase)
	}
	return nil
}

core_types.text:
const (
	SchemaVersion = 1
	// MaxUnits bounds one rollout record so it stays well under the KV value
	// limit while covering every controller and managed host in a cell.
	MaxUnits = 512
	// MaxKnownBad bounds the cell's durable known-bad digest list.
	MaxKnownBad = 256
	maxReason   = 512
)

var (
	ErrInvalid           = errors.New("rollout input is invalid")
	ErrInvalidTransition = errors.New("rollout event is not valid in the current phase")
	ErrTerminal          = errors.New("rollout is in a terminal phase")
	ErrKnownBad          = errors.New("rollout target digest is known bad")
	ErrAttemptsExhausted = errors.New("rollout target digest has no attempts left")
	ErrActiveRollout     = errors.New("another rollout is active in this cell")
	ErrFenced            = errors.New("rollout record belongs to a different authority epoch")
	ErrConflict          = errors.New("rollout record changed concurrently")

	tokenRE  = regexp.MustCompile(`^[a-z0-9][a-z0-9_.-]{0,127}$`)
	nonceRE  = regexp.MustCompile(`^[0-9a-f]{32}$`)
	digestRE = regexp.MustCompile(`^[0-9a-f]{64}$`)
)

// Kind names the executor family that applies a rollout's unit steps.
type Kind string

const (
	KindTerraBase  Kind = "terrabase"
	KindWorkload   Kind = "workload"
	KindController Kind = "controller"
	KindHost       Kind = "host"
)

func (kind Kind) valid() bool {
	return kind == KindTerraBase || kind == KindWorkload || kind == KindController || kind == KindHost
}

// Phase is the rollout-level state. Complete, Aborted and RolledBack are
// terminal; Frozen admits only an explicit operator resume.
type Phase string

const (
	PhasePending     Phase = "pending"
	PhasePreflight   Phase = "preflight"
	PhaseCanary      Phase = "canary"
	PhaseCanarySoak  Phase = "canary-soak"
	PhaseBatch       Phase = "batch"
	PhaseBatchSoak   Phase = "batch-soak"
	PhaseComplete    Phase = "complete"
	PhaseRollingBack Phase = "rolling-back"
	PhaseFrozen      Phase = "frozen"
	PhaseAborted     Phase = "aborted"
	PhaseRolledBack  Phase = "rolled-back"
)

// Terminal reports whether no further transition can change the record.
func (phase Phase) Terminal() bool {
	return phase == PhaseComplete || phase == PhaseAborted || phase == PhaseRolledBack
}

// Active reports whether the phase holds the cell's single rollout slot.
func (phase Phase) Active() bool { return !phase.Terminal() }

func (phase Phase) preparing() bool { return phase == PhaseCanary || phase == PhaseBatch }
func (phase Phase) soaking() bool   { return phase == PhaseCanarySoak || phase == PhaseBatchSoak }

// UnitState is the per-unit progress recorded in the rollout.
type UnitState string

const (
	UnitPending     UnitState = "pending"
	UnitPreparing   UnitState = "preparing"
	UnitSoaking     UnitState = "soaking"
	UnitPromoted    UnitState = "promoted"
	UnitRollingBack UnitState = "rolling-back"
	UnitRolledBack  UnitState = "rolled-back"
	UnitHeld        UnitState = "held"
)

// touched reports whether the unit may run the target digest and therefore
// needs an explicit rollback.
func (state UnitState) touched() bool {
	return state == UnitPreparing || state == UnitSoaking || state == UnitPromoted ||
		state == UnitRollingBack || state == UnitHeld
}

// Unit is one independently replaceable target. Units sharing a Group are
// replicas of one quorum (the controllers, or the seats of a TerraBase
// partition); a wave never takes more than one unit of a group. Seed marks
// the founding controller, which is always replaced last and alone.
type Unit struct {
	ID    string `json:"id"`
	Group string `json:"group"`
	Seed  bool   `json:"seed,omitzero"`
}

// Health is one observed serving report for a unit. ProcessID and StartNonce
// identify the process incarnation, so a restart during soak is detected.
type Health struct {
	Digest     string    `json:"digest"`
	ProcessID  int64     `json:"process_id"`
	StartNonce string    `json:"start_nonce"`
	ObservedAt time.Time `json:"observed_at"`
}

// UnitProgress is the durable per-unit record.
type UnitProgress struct {
	State          UnitState `json:"state"`
	Group          string    `json:"group"`
	Seed           bool      `json:"seed,omitzero"`
	Wave           int       `json:"wave"`
	HealthyReports int       `json:"healthy_reports,omitzero"`
	FirstHealthyAt time.Time `json:"first_healthy_at,omitzero"`
	// LastHealthyAt is the newest counted healthy observation. The soak
	// completes only when the observations themselves span the window.
	LastHealthyAt time.Time `json:"last_healthy_at,omitzero"`
	ProcessID     int64     `json:"process_id,omitzero"`
	StartNonce    string    `json:"start_nonce,omitempty"`
	Attempts      int       `json:"attempts,omitzero"`
}

// Policy is the rollout policy pinned into the record by digest. Durations
// are whole seconds so the canonical encoding is stable across releases.
type Policy struct {
	CanaryUnits             int   `json:"canary_units"`
	BatchSize               int   `json:"batch_size"`
	CanarySoakSeconds       int64 `json:"canary_soak_seconds"`
	BatchSoakSeconds        int64 `json:"batch_soak_seconds"`
	MinHealthyReports       int   `json:"min_healthy_reports"`
	ProofDeadlineSeconds    int64 `json:"proof_deadline_seconds"`
	RollbackDeadlineSeconds int64 `json:"rollback_deadline_seconds"`
	PreflightSeconds        int64 `json:"preflight_seconds"`
	MaxAttempts             int   `json:"max_attempts"`
	MaxRollbackRetries      int   `json:"max_rollback_retries"`
}

core_validation.text:
const (
	QualificationBudget = 10 * time.Minute
	ObservationBudget   = 20 * time.Minute
)

// DefaultPolicy is as fast as a binary-only update allows (user decision
// 2026-10-06): one canary soaks five minutes, then every later wave takes as
// many units as PlanWaves lets it (never two of one group, the seed last and
// alone, so three controllers still move one at a time) and soaks two
// minutes. A unit that restarts on another release, or does not prove the
// target within ten minutes, rolls the rollout back.
func DefaultPolicy() Policy {
	return Policy{
		CanaryUnits: 1, BatchSize: MaxUnits,
		CanarySoakSeconds: int64((5 * time.Minute).Seconds()), BatchSoakSeconds: int64((2 * time.Minute).Seconds()),
		MinHealthyReports: 3, ProofDeadlineSeconds: int64((10 * time.Minute).Seconds()),
		RollbackDeadlineSeconds: int64((10 * time.Minute).Seconds()), PreflightSeconds: int64((10 * time.Minute).Seconds()),
		MaxAttempts: 1, MaxRollbackRetries: 3,
	}
}

// Validate rejects policies that could skip the canary, soak or deadlines.
func (policy Policy) Validate() error {
	if policy.CanaryUnits < 1 || policy.CanaryUnits > MaxUnits || policy.BatchSize < 1 || policy.BatchSize > MaxUnits ||
		policy.CanarySoakSeconds < 0 || policy.BatchSoakSeconds < 0 || policy.MinHealthyReports < 1 ||
		policy.ProofDeadlineSeconds < 1 || policy.RollbackDeadlineSeconds < 1 || policy.PreflightSeconds < 1 ||
		policy.MaxAttempts < 1 || policy.MaxRollbackRetries < 0 {
		return fmt.Errorf("%w: policy bounds", ErrInvalid)
	}
	return nil
}

// Digest is SHA-256 of the canonical policy encoding.
func (policy Policy) Digest() (string, error) {
	encoded, err := protocol.EncodeJSON(policy)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(encoded)
	return hex.EncodeToString(sum[:]), nil
}

func seconds(value int64) time.Duration { return time.Duration(value) * time.Second }

// Record is the durable rollout state. It is written by CAS on its KV
// revision and fenced by AuthorityEpoch.
type Record struct {
	SchemaVersion  int                     `json:"schema_version"`
	RolloutID      string                  `json:"rollout_id"`
	Kind           Kind                    `json:"kind"`
	Cell           string                  `json:"cell"`
	FromDigest     string                  `json:"from_digest"`
	ToDigest       string                  `json:"to_digest"`
	Policy         Policy                  `json:"policy"`
	PolicyDigest   string                  `json:"policy_digest"`
	Phase          Phase                   `json:"phase"`
	WaveIndex      int                     `json:"wave_index"`
	Waves          [][]string              `json:"waves"`
	Units          map[string]UnitProgress `json:"units"`
	RollbackOrder  []string                `json:"rollback_order,omitempty"`
	KnownBad       []string                `json:"known_bad,omitempty"`
	StartedAt      time.Time               `json:"started_at"`
	PhaseStartedAt time.Time               `json:"phase_started_at"`
	PhaseDeadline  time.Time               `json:"phase_deadline,omitzero"`
	AuthorityEpoch uint64                  `json:"authority_epoch"`
	Reason         string                  `json:"reason,omitempty"`
}

// Validate checks the record's structural invariants. It is applied on every
// decode and before every store write.
func (record Record) Validate() error {
	if record.SchemaVersion != SchemaVersion || !entityid.Valid(record.RolloutID) || !record.Kind.valid() ||
		!tokenRE.MatchString(record.Cell) || !digestRE.MatchString(record.FromDigest) || !digestRE.MatchString(record.ToDigest) ||
		record.FromDigest == record.ToDigest || record.AuthorityEpoch == 0 || record.StartedAt.IsZero() ||
		record.PhaseStartedAt.IsZero() || len(record.Reason) > maxReason || len(record.KnownBad) > MaxKnownBad {
		return fmt.Errorf("%w: record identity", ErrInvalid)
	}
	if err := record.Policy.Validate(); err != nil {
		return err
	}
	if digest, err := record.Policy.Digest(); err != nil || digest != record.PolicyDigest {
		return fmt.Errorf("%w: policy digest", ErrInvalid)
	}
	switch record.Phase {
	case PhasePending, PhasePreflight, PhaseCanary, PhaseCanarySoak, PhaseBatch, PhaseBatchSoak,
		PhaseComplete, PhaseRollingBack, PhaseFrozen, PhaseAborted, PhaseRolledBack:
	default:
		return fmt.Errorf("%w: phase", ErrInvalid)
	}
	if len(record.Waves) == 0 || len(record.Units) == 0 || len(record.Units) > MaxUnits ||
		record.WaveIndex < 0 || record.WaveIndex >= len(record.Waves) {
		return fmt.Errorf("%w: waves", ErrInvalid)
	}
	seen := make(map[string]struct{}, len(record.Units))
	for wave, ids := range record.Waves {
		if len(ids) == 0 {
			return fmt.Errorf("%w: empty wave", ErrInvalid)
		}
		for _, id := range ids {
			progress, exists := record.Units[id]
			if _, duplicate := seen[id]; duplicate || !exists || progress.Wave != wave || !tokenRE.MatchString(progress.Group) {
				return fmt.Errorf("%w: wave unit %q", ErrInvalid, id)
			}
			seen[id] = struct{}{}
		}
	}
	if len(seen) != len(record.Units) {
		return fmt.Errorf("%w: unit outside every wave", ErrInvalid)
	}
	for _, id := range record.RollbackOrder {
		if _, exists := record.Units[id]; !exists {
			return fmt.Errorf("%w: rollback unit %q", ErrInvalid, id)
		}
	}
	for _, digest := range record.KnownBad {
		if !digestRE.MatchString(digest) {
			return fmt.Errorf("%w: known-bad digest", ErrInvalid)
		}
	}
	if slices.Contains(record.KnownBad, record.FromDigest) {
		return fmt.Errorf("%w: rollback target is known bad", ErrInvalid)
	}
	return record.validatePhaseUnits()
}

// validatePhaseUnits rejects phase and unit-state contradictions that Apply
// never produces, so a record built outside Apply is refused at the storage
// boundary instead of driving effects.
func (record Record) validatePhaseUnits() error {
	for _, id := range record.Waves[record.WaveIndex] {
		state := record.Units[id].State
		if record.Phase.soaking() && state != UnitSoaking ||
			record.Phase.preparing() && state != UnitPreparing && state != UnitSoaking {
			return fmt.Errorf("%w: phase %s contradicts unit %q in state %s", ErrInvalid, record.Phase, id, state)
		}
	}
	if record.Phase == PhaseRollingBack && record.rollbackHead() == "" {
		return fmt.Errorf("%w: rolling back without a unit to roll back", ErrInvalid)
	}
	return nil
}

func (record Record) abortedBeforeUpdate() bool {
	if record.Phase != PhaseAborted || len(record.RollbackOrder) != 0 {
		return false
	}
	for _, progress := range record.Units {
		if progress.State != UnitPending {
			return false
		}
	}
	return true
}

// Clone returns a deep copy so transitions never alias a caller's record.
func (record Record) Clone() Record {
	clone := record
	clone.Waves = make([][]string, len(record.Waves))
	for index, wave := range record.Waves {
		clone.Waves[index] = slices.Clone(wave)
	}
	clone.Units = make(map[string]UnitProgress, len(record.Units))
	for id, progress := range record.Units {
		clone.Units[id] = progress
	}
	clone.RollbackOrder = slices.Clone(record.RollbackOrder)
	clone.KnownBad = slices.Clone(record.KnownBad)
	return clone
}

// InFlight returns the units moving forward to ToDigest that have not yet
// been promoted. Invariant (d) bounds them by the wave size and keeps them in
// pairwise distinct groups.
func (record Record) InFlight() []string {
	var units []string
	for id, progress := range record.Units {
		if progress.State == UnitPreparing || progress.State == UnitSoaking {
			units = append(units, id)
		}
	}
	slices.Sort(units)
	return units
}

// OperationID derives the idempotent executor operation identity for one
// unit step, so a retried transition never creates a second operation.
func OperationID(rolloutID, unit string, phase Phase, attempt int) string {
	return entityid.Derive("rollout", rolloutID, unit, string(phase), fmt.Sprint(attempt))
}

