func (s Snapshot) CanMutate() bool {
	return entityid.Valid(s.DeploymentID) && s.Ready && s.Leader && s.Epoch > 0 && s.Revision > 0 &&
		!s.ExpiresAt.IsZero() && time.Now().Before(s.ExpiresAt)
}

entity_id.text:
// New returns a cryptographically random ULID, monotonic within a millisecond.
func New() string { return NewAt(time.Now()) }

// NewAt stamps an ID with the record's time. The entropy reader is shared and
// serialized because the library's monotonic reader is not concurrency-safe.
func NewAt(at time.Time) string {
	mu.Lock()
	defer mu.Unlock()
	return ulid.MustNew(ulid.Timestamp(at), entropy).String()
}

// Parse accepts only nonzero, uppercase, 26-character Crockford ULIDs.
func Parse(value string) (ulid.ULID, error) {
	id, err := ulid.ParseStrict(value)
	if err != nil || id == (ulid.ULID{}) || id.String() != value {
		return ulid.ULID{}, errors.New("entity ID must be a canonical uppercase ULID")
	}
	return id, nil
}

func Valid(value string) bool {
	_, err := Parse(value)
	return err == nil
}

// Derive gives an idempotent operation a stable ULID. A zero timestamp marks
// derived identities as having no creation time; the 80 entropy bits bind the
// domain-separated input. New entities use New instead.
func Derive(domain string, values ...string) string {
	h := sha256.New()
	for _, value := range append([]string{domain}, values...) {
		var size [8]byte
		binary.BigEndian.PutUint64(size[:], uint64(len(value)))
		h.Write(size[:])
		h.Write([]byte(value))
	}
	return ulid.MustNew(0, bytes.NewReader(h.Sum(nil)[:10])).String()
}

protocol.text:
func EncodeJSON(value any) ([]byte, error) {
	encoded, err := json.Marshal(value, json.Deterministic(true))
	if err != nil {
		return nil, fmt.Errorf("encode protocol JSON: %w", err)
	}
	return encoded, nil
}

// DecodeStrict decodes one bounded JSON value, rejecting duplicate names, invalid
// UTF-8, and unknown struct members. The Go 1.27 JSON v2 decoder rejects duplicate
// object names and invalid UTF-8 by default; RejectUnknownMembers closes the
// remaining permissive struct-decoding path.
func DecodeStrict(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, true)
}

// DecodeTolerant is DecodeStrict for records a newer binary may have written:
// it skips members this binary does not know, so binary N-1 reads N's records.
// Duplicate names, invalid UTF-8 and the size limit still fail. A record's
// schema version names its breaking changes, and its reader checks it; a new
// member needs a safe zero value, since an older writer drops it.
func DecodeTolerant(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, false)
}

func decode(data []byte, destination any, maxBytes int, rejectUnknown bool) error {
	if maxBytes == 0 {
		maxBytes = DefaultMaxJSONBytes
	}
	if maxBytes < 0 {
		return fmt.Errorf("%w: negative byte limit", ErrInvalidJSON)
	}
	if len(data) > maxBytes {
		return ErrJSONTooLarge
	}
	if !utf8.Valid(data) {
		return fmt.Errorf("%w: invalid UTF-8", ErrInvalidJSON)
	}
	if err := json.Unmarshal(data, destination,
		json.RejectUnknownMembers(rejectUnknown),
		jsontext.AllowDuplicateNames(false),
	); err != nil {
		return fmt.Errorf("decode protocol JSON: %w", err)
	}
	return nil
}

empty_receipt_guard.text:
func DecodeEnvelope(encoded []byte) (Envelope, error) {
	if len(encoded) == 0 || len(encoded) > MaxEnvelopeBytes {
		return Envelope{}, fmt.Errorf("%w: envelope is empty or too large", ErrInvalid)
	}
	var envelope Envelope
	if err := protocol.DecodeStrict(encoded, &envelope, MaxEnvelopeBytes); err != nil {
		return Envelope{}, fmt.Errorf("decode trust envelope: %w", err)
	}
	canonical, err := EncodeEnvelope(envelope)
	if err != nil {
		return Envelope{}, err
	}
	if string(canonical) != string(encoded) {
		return Envelope{}, fmt.Errorf("%w: envelope JSON is not canonical", ErrInvalid)
	}
	return envelope, nil
}

store_decisions.text:
func ReleaseCorrelation(digest string) string { return "release:" + digest }

// recordAdmitted journals a newly created rollout record as the chain root.
// It runs only after the KV create committed, so an idempotent Begin replay
// that returns the existing record does not record again.
func recordAdmitted(ctx context.Context, record Record) {
	id := decisionlog.Record(ctx, decisionlog.Decision{
		Region:  record.Cell,
		Actor:   decisionlog.Actor{Slice: "rollout"},
		Kind:    decisionlog.KindReleaseAdmitted,
		Subject: decisionlog.Subject{Kind: "release", ID: record.ToDigest, Name: string(record.Kind) + "/" + record.RolloutID},
		Summary: fmt.Sprintf("Admitted %s rollout %s of %d units in %d waves", record.Kind, record.RolloutID,
			len(record.Units), len(record.Waves)),
		Reason: "The target digest is not known bad and has attempts left.",
		Rule:   "rollout.begin",
		Status: decisionlog.StatusPending,
		Epoch:  record.AuthorityEpoch,
		Attrs: map[string]string{"rollout": record.RolloutID, "from": record.FromDigest,
			"policy": record.PolicyDigest},
	})
	decisionlog.Correlate(ReleaseCorrelation(record.ToDigest), id)
}

// recordTransition journals a committed phase change. Commit calls it after
// the CAS succeeded, so every transition is recorded exactly once.
func recordTransition(ctx context.Context, previous, next Record) {
	if previous.Phase == next.Phase && previous.WaveIndex == next.WaveIndex {
		return
	}
	kind, status, summary := transitionDecision(previous, next)
	if kind == "" {
		return
	}
	decisionlog.Record(ctx, decisionlog.Decision{
		Region:   next.Cell,
		Actor:    decisionlog.Actor{Slice: "rollout"},
		Kind:     kind,
		Subject:  decisionlog.Subject{Kind: "release", ID: next.ToDigest, Name: string(next.Kind) + "/" + next.RolloutID},
		Summary:  summary,
		Reason:   next.Reason,
		Rule:     "rollout." + string(next.Phase),
		Status:   status,
		Epoch:    next.AuthorityEpoch,
		ParentID: decisionlog.Correlated(ReleaseCorrelation(next.ToDigest)),
		Signals: []decisionlog.Signal{{Name: "wave", Value: float64(next.WaveIndex + 1),
			Comparison: "<=", Threshold: decisionlog.Threshold(float64(len(next.Waves)))}},
		Attrs: map[string]string{"rollout": next.RolloutID, "from_phase": string(previous.Phase),
			"phase": string(next.Phase), "wave": strconv.Itoa(next.WaveIndex)},
	})
}

func transitionDecision(previous, next Record) (decisionlog.Kind, decisionlog.Status, string) {
	id := next.RolloutID
	switch next.Phase {
	case PhaseCanary:
		return decisionlog.KindUpgradeStarted, decisionlog.StatusInProgress, "Started canary of rollout " + id
	case PhaseBatch:
		if previous.Phase == PhaseCanarySoak {
			return decisionlog.KindCanaryPromoted, decisionlog.StatusInProgress, "Promoted the canary of rollout " + id
		}
		return decisionlog.KindBatchPromoted, decisionlog.StatusInProgress,
			fmt.Sprintf("Promoted wave %d of rollout %s", next.WaveIndex, id)
	case PhaseComplete:
		return decisionlog.KindRolloutCompleted, decisionlog.StatusSucceeded, "Completed rollout " + id
	case PhaseRollingBack:
		return decisionlog.KindRollback, decisionlog.StatusInProgress, "Rolling back rollout " + id
	case PhaseRolledBack:
		return decisionlog.KindRollback, decisionlog.StatusRolledBack, "Rolled back rollout " + id
	case PhaseFrozen:
		return decisionlog.KindFrozen, decisionlog.StatusPending, "Froze rollout " + id + " for operator review"
	case PhaseAborted:
		return decisionlog.KindHeld, decisionlog.StatusFailed, "Aborted rollout " + id
	}
	return "", "", ""
}

decision_log.text:
func Default() Recorder {
	if holder := defaultRecorder.Load(); holder != nil {
		return holder.recorder
	}
	return nil
}

// Record journals one decision with the process-wide recorder and returns
// its ID, so a caller can link later decisions to it with ParentID. It never
// blocks on the network and never fails; see the package documentation.
func Record(ctx context.Context, decision Decision) string {
	if recorder := Default(); recorder != nil {
		return recorder.Record(ctx, decision)
	}
	return LogRecorder{}.Record(ctx, decision)
}

// LogRecorder writes decisions to the default structured logger. It is the
// fallback before a Journal is installed, and the recorder of processes
// without a regional stream (one-shot CLI commands, hosts).
type LogRecorder struct {
	Logger *slog.Logger
}

// Record logs the decision and returns its ID.
func (recorder LogRecorder) Record(ctx context.Context, decision Decision) string {
	decision = decision.Normalize(time.Now())
	logger := recorder.Logger
	if logger == nil {
		logger = slog.Default()
	}
	attrs := []slog.Attr{slog.String(observability.ComponentKey, "decision"), slog.Bool(observability.EventKey, true),
		slog.String("decision_id", decision.ID),
		slog.String("kind", string(decision.Kind)), slog.String("actor", decision.Actor.Slice),
		slog.String("subject", decision.Subject.String()), slog.String("status", string(decision.Status))}
	if decision.Region != "" {
		attrs = append(attrs, slog.String("region", decision.Region))
	}
	if decision.Reason != "" {
		attrs = append(attrs, slog.String("reason", decision.Reason))
	}
	if decision.ParentID != "" {
		attrs = append(attrs, slog.String("parent_id", decision.ParentID))
	}
	logger.LogAttrs(ctx, slog.LevelInfo, decision.Summary, attrs...)
	return decision.ID
}

correlation.text:
func Correlate(key, id string) {
	if key == "" || id == "" {
		return
	}
	correlations.Lock()
	defer correlations.Unlock()
	if _, exists := correlations.ids[key]; !exists {
		correlations.order = append(correlations.order, key)
	}
	correlations.ids[key] = id
	for len(correlations.order) > maxCorrelations {
		delete(correlations.ids, correlations.order[0])
		correlations.order = correlations.order[1:]
	}
}

// Correlated returns the decision ID remembered for key, or "".
func Correlated(key string) string {
	correlations.Lock()
	defer correlations.Unlock()
	return correlations.ids[key]
}

